 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29033", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29034", "mode": "normal", "text": "**Required fields:**", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29035", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29037", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29038", "mode": "normal", "text": "\\| Field                 | Description                                  |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29039", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29041", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29042", "mode": "normal", "text": "\\| :-------------------- | :------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29043", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29045", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29046", "mode": "normal", "text": "\\| `command`             | The LSP binary to execute (must be in PATH)  |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29047", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29049", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29050", "mode": "normal", "text": "\\| `extensionToLanguage` | Maps file extensions to language identifiers |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29051", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29053", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29054", "mode": "normal", "text": "**Optional fields:**", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29055", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29057", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29058", "mode": "normal", "text": "\\| Field                   | Description                                               |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29059", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29061", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29062", "mode": "normal", "text": "\\| :---------------------- | :-------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29063", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29065", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29066", "mode": "normal", "text": "\\| `args`                  | Command-line arguments for the LSP server                 |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29067", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29069", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29070", "mode": "normal", "text": "\\| `transport`             | Communication transport: `stdio` (default) or `socket`    |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29071", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29073", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29074", "mode": "normal", "text": "\\| `env`                   | Environment variables to set when starting the server     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29075", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29077", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29078", "mode": "normal", "text": "\\| `initializationOptions` | Options passed to the server during initialization        |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29079", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29081", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29082", "mode": "normal", "text": "\\| `settings`              | Settings passed via `workspace/didChangeConfiguration`    |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29083", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29085", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29086", "mode": "normal", "text": "\\| `workspaceFolder`       | Workspace folder path for the server                      |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29087", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29089", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29090", "mode": "normal", "text": "\\| `startupTimeout`        | Max time to wait for server startup (milliseconds)        |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29091", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29093", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29094", "mode": "normal", "text": "\\| `shutdownTimeout`       | Max time to wait for graceful shutdown (milliseconds)     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29095", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29097", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29098", "mode": "normal", "text": "\\| `restartOnCrash`        | Whether to automatically restart the server if it crashes |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29099", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29101", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29102", "mode": "normal", "text": "\\| `maxRestarts`           | Maximum number of restart attempts before giving up       |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29103", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29105", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29106", "mode": "normal", "text": "<Warning>", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29107", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29109", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29110", "mode": "normal", "text": "**You must install the language server binary separately.** LSP plugins configure how Claude Code connects to a language server, but they don''t include the server itself. If you see `Executable not found in $PATH` in the `/plugin` Errors tab, install the required binary for your language.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29111", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29113", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29114", "mode": "normal", "text": "</Warning>", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29115", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29117", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29118", "mode": "normal", "text": "**Available LSP plugins:**", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29119", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29121", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29122", "mode": "normal", "text": "\\| Plugin           | Language server            | Install command                                                                            |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29123", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29125", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29126", "mode": "normal", "text": "\\| :--------------- | :------------------------- | :----------------------------------------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29127", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29129", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29130", "mode": "normal", "text": "\\| `pyright-lsp`    | Pyright (Python)           | `pip install pyright` or `npm install -g pyright`                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29131", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29133", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29134", "mode": "normal", "text": "\\| `typescript-lsp` | TypeScript Language Server | `npm install -g typescript-language-server typescript`                                     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29135", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29137", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29138", "mode": "normal", "text": "\\| `rust-lsp`       | rust-analyzer              | [See rust-analyzer installation](https://rust-analyzer.github.io/manual.html#installation) |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29139", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29141", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29142", "mode": "normal", "text": "Install the language server first, then install the plugin from the marketplace.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29143", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29145", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29146", "mode": "normal", "text": "---", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29147", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29149", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29150", "mode": "normal", "text": "## Plugin installation scopes", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29151", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29153", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29154", "mode": "normal", "text": "When you install a plugin, you choose a **scope** that determines where the plugin is available and who else can use it:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29155", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29157", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29158", "mode": "normal", "text": "\\| Scope     | Settings file                 | Use case                                                 |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29159", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29161", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29162", "mode": "normal", "text": "\\| :-------- | :---------------------------- | :------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29163", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29165", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29166", "mode": "normal", "text": "\\| `user`    | `~/.claude/settings.json`     | Personal plugins available across all projects (default) |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29167", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29169", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29170", "mode": "normal", "text": "\\| `project` | `.claude/settings.json`       | Team plugins shared via version control                  |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29171", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29173", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29174", "mode": "normal", "text": "\\| `local`   | `.claude/settings.local.json` | Project-specific plugins, gitignored                     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29175", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29177", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29178", "mode": "normal", "text": "\\| `managed` | `managed-settings.json`       | Managed plugins (read-only, update only)                 |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29179", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29181", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29182", "mode": "normal", "text": "Plugins use the same scope system as other Claude Code configurations. For installation instructions and scope flags, see [Install plugins](/en/discover-plugins#install-plugins). For a complete explanation of scopes, see [Configuration scopes](/en/settings#configuration-scopes).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29183", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29185", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29186", "mode": "normal", "text": "---", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29187", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29189", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29190", "mode": "normal", "text": "## Plugin manifest schema", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29191", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29193", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29194", "mode": "normal", "text": "The `.claude-plugin/plugin.json` file defines your plugin''s metadata and configuration. This section documents all supported fields and options.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29195", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29197", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29198", "mode": "normal", "text": "The manifest is optional. If omitted, Claude Code auto-discovers components in [default locations](#file-locations-reference) and derives the plugin name from the directory name. Use a manifest when you need to provide metadata or custom component paths.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29199", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29201", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29202", "mode": "normal", "text": "### Complete schema", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29203", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29205", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29206", "mode": "normal", "text": "```json theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29207", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29209", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29210", "mode": "normal", "text": "{ ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29211", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29213", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29214", "mode": "normal", "text": "  \"name\": \"plugin-name\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29215", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29217", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29218", "mode": "normal", "text": "  \"version\": \"1.2.0\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29219", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29221", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29222", "mode": "normal", "text": "  \"description\": \"Brief plugin description\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29223", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29225", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29226", "mode": "normal", "text": "  \"author\": { ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29227", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29229", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29230", "mode": "normal", "text": "    \"name\": \"Author Name\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29231", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29233", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29234", "mode": "normal", "text": "    \"email\": \"author@example.com\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29235", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29237", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29238", "mode": "normal", "text": "    \"url\": \"https://github.com/author\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29239", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29241", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29242", "mode": "normal", "text": "  }, ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29243", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29245", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29246", "mode": "normal", "text": "  \"homepage\": \"https://docs.example.com/plugin\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29247", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29249", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29250", "mode": "normal", "text": "  \"repository\": \"https://github.com/author/plugin\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29251", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29253", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29254", "mode": "normal", "text": "  \"license\": \"MIT\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29255", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29257", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29258", "mode": "normal", "text": "  \"keywords\": [\"keyword1\", \"keyword2\"], ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29259", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29261", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29262", "mode": "normal", "text": "  \"commands\": [\"./custom/commands/special.md\"], ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29263", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29265", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29266", "mode": "normal", "text": "  \"agents\": \"./custom/agents/\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29267", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29269", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29270", "mode": "normal", "text": "  \"skills\": \"./custom/skills/\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29271", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29273", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29274", "mode": "normal", "text": "  \"hooks\": \"./config/hooks.json\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29275", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29277", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29278", "mode": "normal", "text": "  \"mcpServers\": \"./mcp-config.json\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29279", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29281", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29282", "mode": "normal", "text": "  \"outputStyles\": \"./styles/\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29283", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29285", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29286", "mode": "normal", "text": "  \"lspServers\": \"./.lsp.json\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29287", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29289", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29290", "mode": "normal", "text": "} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29291", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29293", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29294", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29295", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29297", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29298", "mode": "normal", "text": "### Required fields", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29299", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29301", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29302", "mode": "normal", "text": "If you include a manifest, `name` is the only required field.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29303", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29305", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29306", "mode": "normal", "text": "\\| Field  | Type   | Description                               | Example              |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29307", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29309", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29310", "mode": "normal", "text": "\\| :----- | :----- | :---------------------------------------- | :------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29311", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29313", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29314", "mode": "normal", "text": "\\| `name` | string | Unique identifier (kebab-case, no spaces) | `\"deployment-tools\"` |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29315", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29317", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29318", "mode": "normal", "text": "This name is used for namespacing components. For example, in the UI, the", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29319", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29321", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29322", "mode": "normal", "text": "agent `agent-creator` for the plugin with name `plugin-dev` will appear as", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29323", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29325", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29326", "mode": "normal", "text": "`plugin-dev:agent-creator`.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29327", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "29329", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "29330", "mode": "normal", "text": "### Metadata fields", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"