rmat": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32521", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "32522", "mode": "normal", "text": "      }} else {{ ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32523", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32525", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "32526", "mode": "normal", "text": "        const li = document.createElement(''li''); li.className = ''file''; ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32527", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32529", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "32530", "mode": "normal", "text": "        li.innerHTML = `<span class=\"dot\" style=\"background:${{colors[node.ext]||''#6b7280''}}\"></span>${{node.name}}<span class=\"size\">${{fmt(node.size)}}</span>`; ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32531", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32533", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "32534", "mode": "normal", "text": "        parent.appendChild(li); ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "32535", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction