 0, "version": 1, "children": [{"id": "35890", "mode": "normal", "text": "hooks: ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35891", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35893", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35894", "mode": "normal", "text": "  PreToolUse: ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35895", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35897", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35898", "mode": "normal", "text": "    - matcher: \"Bash\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35899", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35901", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35902", "mode": "normal", "text": "      hooks: ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35903", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35905", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35906", "mode": "normal", "text": "        - type: command", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35907", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35909", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35910", "mode": "normal", "text": "          command: \"./scripts/security-check.sh\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35911", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35913", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35914", "mode": "normal", "text": "--- ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35915", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35917", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35918", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35919", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35921", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35922", "mode": "normal", "text": "Agents use the same format in their YAML frontmatter.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35923", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35925", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35926", "mode": "normal", "text": "### The `/hooks` menu", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35927", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35929", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35930", "mode": "normal", "text": "Type `/hooks` in Claude Code to open the interactive hooks manager, where you can view, add, and delete hooks without editing settings files directly. For a step-by-step walkthrough, see [Set up your first hook](/en/hooks-guide#set-up-your-first-hook) in the guide.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35931", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35933", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35934", "mode": "normal", "text": "Each hook in the menu is labeled with a bracket prefix indicating its source:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35935", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35937", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35938", "mode": "normal", "text": "- `[User]`: from `~/.claude/settings.json`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35939", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35941", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35942", "mode": "normal", "text": "- `[Project]`: from `.claude/settings.json`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35943", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35945", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35946", "mode": "normal", "text": "- `[Local]`: from `.claude/settings.local.json`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35947", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35949", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35950", "mode": "normal", "text": "- `[Plugin]`: from a plugin''s `hooks/hooks.json`, read-only", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35951", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35953", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35954", "mode": "normal", "text": "### Disable or remove hooks", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35955", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35957", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35958", "mode": "normal", "text": "To remove a hook, delete its entry from the settings JSON file, or use the `/hooks` menu and select the hook to delete it.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35959", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35961", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35962", "mode": "normal", "text": "To temporarily disable all hooks without removing them, set `\"disableAllHooks\": true` in your settings file or use the toggle in the `/hooks` menu. There is no way to disable an individual hook while keeping it in the configuration.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35963", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35965", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35966", "mode": "normal", "text": "Direct edits to hooks in settings files don''t take effect immediately. Claude Code captures a snapshot of hooks at startup and uses it throughout the session. This prevents malicious or accidental hook modifications from taking effect mid-session without your review. If hooks are modified externally, Claude Code warns you and requires review in the `/hooks` menu before changes apply.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35967", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35969", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35970", "mode": "normal", "text": "## Hook input and output", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35971", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35973", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35974", "mode": "normal", "text": "Hooks receive JSON data via stdin and communicate results through exit codes, stdout, and stderr. This section covers fields and behavior common to all events. Each event''s section under [Hook events](#hook-events) includes its specific input schema and decision control options.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35975", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35977", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35978", "mode": "normal", "text": "### Common input fields", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35979", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35981", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35982", "mode": "normal", "text": "All hook events receive these fields via stdin as JSON, in addition to event-specific fields documented in each [hook event](#hook-events) section:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35983", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35985", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35986", "mode": "normal", "text": "\\| Field             | Description                                                                                                                                |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35987", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35989", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35990", "mode": "normal", "text": "\\| :---------------- | :----------------------------------------------------------------------------------------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35991", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35993", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35994", "mode": "normal", "text": "\\| `session_id`      | Current session identifier                                                                                                                 |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35995", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35997", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "35998", "mode": "normal", "text": "\\| `transcript_path` | Path to conversation JSON                                                                                                                  |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "35999", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36001", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36002", "mode": "normal", "text": "\\| `cwd`             | Current working directory when the hook is invoked                                                                                         |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36003", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36005", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36006", "mode": "normal", "text": "\\| `permission_mode` | Current [permission mode](/en/permissions#permission-modes): `\"default\"`, `\"plan\"`, `\"acceptEdits\"`, `\"dontAsk\"`, or `\"bypassPermissions\"` |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36007", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36009", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36010", "mode": "normal", "text": "\\| `hook_event_name` | Name of the event that fired                                                                                                               |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36011", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36013", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36014", "mode": "normal", "text": "For example, a `PreToolUse` hook for a Bash command receives this on stdin:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36015", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36017", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36018", "mode": "normal", "text": "```json theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36019", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36021", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36022", "mode": "normal", "text": "{ ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36023", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36025", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36026", "mode": "normal", "text": "  \"session_id\": \"abc123\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36027", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36029", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36030", "mode": "normal", "text": "  \"transcript_path\": \"/home/user/.claude/projects/.../transcript.jsonl\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36031", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36033", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36034", "mode": "normal", "text": "  \"cwd\": \"/home/user/my-project\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36035", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36037", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36038", "mode": "normal", "text": "  \"permission_mode\": \"default\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36039", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36041", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36042", "mode": "normal", "text": "  \"hook_event_name\": \"PreToolUse\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36043", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36045", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36046", "mode": "normal", "text": "  \"tool_name\": \"Bash\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36047", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36049", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36050", "mode": "normal", "text": "  \"tool_input\": { ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36051", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36053", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36054", "mode": "normal", "text": "    \"command\": \"npm test\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36055", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36057", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36058", "mode": "normal", "text": "  } ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36059", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36061", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36062", "mode": "normal", "text": "} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36063", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36065", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36066", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36067", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36069", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36070", "mode": "normal", "text": "The `tool_name` and `tool_input` fields are event-specific. Each [hook event](#hook-events) section documents the additional fields for that event.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36071", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36073", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36074", "mode": "normal", "text": "### Exit code output", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36075", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36077", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36078", "mode": "normal", "text": "The exit code from your hook command tells Claude Code whether the action should proceed, be blocked, or be ignored.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36079", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36081", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36082", "mode": "normal", "text": "**Exit 0** means success. Claude Code parses stdout for [JSON output fields](#json-output). JSON output is only processed on exit 0. For most events, stdout is only shown in verbose mode (`Ctrl+O`). The exceptions are `UserPromptSubmit` and `SessionStart`, where stdout is added as context that Claude can see and act on.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36083", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36085", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36086", "mode": "normal", "text": "**Exit 2** means a blocking error. Claude Code ignores stdout and any JSON in it. Instead, stderr text is fed back to Claude as an error message. The effect depends on the event: `PreToolUse` blocks the tool call, `UserPromptSubmit` rejects the prompt, and so on. See [exit code 2 behavior](#exit-code-2-behavior-per-event) for the full list.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36087", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36089", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36090", "mode": "normal", "text": "**Any other exit code** is a non-blocking error. stderr is shown in verbose mode (`Ctrl+O`) and execution continues.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36091", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36093", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36094", "mode": "normal", "text": "For example, a hook command script that blocks dangerous Bash commands:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36095", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36097", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36098", "mode": "normal", "text": "```bash theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36099", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36101", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36102", "mode": "normal", "text": "#!/bin/bash", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36103", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36105", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36106", "mode": "normal", "text": "# Reads JSON input from stdin, checks the command", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36107", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36109", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36110", "mode": "normal", "text": "command=$(jq -r ''.tool_input.command'' < /dev/stdin) ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36111", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36113", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36115", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36117", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36118", "mode": "normal", "text": "if [[ \"$command\" == rm* ]]; then", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36119", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36121", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36122", "mode": "normal", "text": "  echo \"Blocked: rm commands are not allowed\" >&2", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36123", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36125", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36126", "mode": "normal", "text": "  exit 2  # Blocking error: tool call is prevented", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36127", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36129", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36130", "mode": "normal", "text": "fi", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36131", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36133", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36135", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36137", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36138", "mode": "normal", "text": "exit 0  # Success: tool call proceeds", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36139", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36141", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36142", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36143", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36145", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36146", "mode": "normal", "text": "#### Exit code 2 behavior per event", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36147", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36149", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36150", "mode": "normal", "text": "Exit code 2 is the way a hook signals \"stop, don''t do this.\" The effect depends on the event, because some events represent actions that can be blocked (like a tool call that hasn''t happened yet) and others represent things that already happened or can''t be prevented.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36151", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36153", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36154", "mode": "normal", "text": "\\| Hook event           | Can block? | What happens on exit 2                                             |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36155", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36157", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36158", "mode": "normal", "text": "\\| :------------------- | :--------- | :----------------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36159", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36161", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36162", "mode": "normal", "text": "\\| `PreToolUse`         | Yes        | Blocks the tool call                                               |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36163", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36165", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36166", "mode": "normal", "text": "\\| `PermissionRequest`  | Yes        | Denies the permission                                              |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36167", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36169", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36170", "mode": "normal", "text": "\\| `UserPromptSubmit`   | Yes        | Blocks prompt processing and erases the prompt                     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36171", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36173", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36174", "mode": "normal", "text": "\\| `Stop`               | Yes        | Prevents Claude from stopping, continues the conversation          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36175", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36177", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36178", "mode": "normal", "text": "\\| `SubagentStop`       | Yes        | Prevents the subagent from stopping                                |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36179", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36181", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36182", "mode": "normal", "text": "\\| `TeammateIdle`       | Yes        | Prevents the teammate from going idle (teammate continues working) |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36183", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36185", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36186", "mode": "normal", "text": "\\| `TaskCompleted`      | Yes        | Prevents the task from being marked as completed                   |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36187", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36189", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36190", "mode": "normal", "text": "\\| `PostToolUse`        | No         | Shows stderr to Claude (tool already ran)                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36191", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36193", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36194", "mode": "normal", "text": "\\| `PostToolUseFailure` | No         | Shows stderr to Claude (tool already failed)                       |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36195", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36197", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36198", "mode": "normal", "text": "\\| `Notification`       | No         | Shows stderr to user only                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36199", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36201", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36202", "mode": "normal", "text": "\\| `SubagentStart`      | No         | Shows stderr to user only                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36203", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36205", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36206", "mode": "normal", "text": "\\| `SessionStart`       | No         | Shows stderr to user only                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36207", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36209", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36210", "mode": "normal", "text": "\\| `SessionEnd`         | No         | Shows stderr to user only                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36211", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36213", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36214", "mode": "normal", "text": "\\| `PreCompact`         | No         | Shows stderr to user only                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36215", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36217", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36218", "mode": "normal", "text": "### JSON output", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36219", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36221", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36222", "mode": "normal", "text": "Exit codes let you allow or block, but JSON output gives you finer-grained control. Instead of exiting with code 2 to block, exit 0 and print a JSON object to stdout. Claude Code reads specific fields from that JSON to control behavior, including [decision control](#decision-control) for blocking, allowing, or escalating to the user.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36223", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36225", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36226", "mode": "normal", "text": "<Note>", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36227", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36229", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36230", "mode": "normal", "text": "You must choose one approach per hook, not both: either use exit codes alone for signaling, or exit 0 and print JSON for structured control. Claude Code only processes JSON on exit 0. If you exit 2, any JSON is ignored.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36231", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36233", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36234", "mode": "normal", "text": "</Note>", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36235", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36237", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36238", "mode": "normal", "text": "Your hook''s stdout must contain only the JSON object. If your shell profile prints text on startup, it can interfere with JSON parsing. See [JSON validation failed](/en/hooks-guide#json-validation-failed) in the troubleshooting guide.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36239", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36241", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36242", "mode": "normal", "text": "The JSON object supports three kinds of fields:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36243", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36245", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36246", "mode": "normal", "text": "- **Universal fields** like `continue` work across all events. These are listed in the table below.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36247", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36249", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36250", "mode": "normal", "text": "- **Top-level `decision` and `reason`** are used by some events to block or provide feedback.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36251", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36253", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36254", "mode": "normal", "text": "- **`hookSpecificOutput`** is a nested object for events that need richer control. It requires a `hookEventName` field set to the event name.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36255", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36257", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36258", "mode": "normal", "text": "\\| Field            | Default | Description                                                                                                                |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36259", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36261", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36262", "mode": "normal", "text": "\\| :--------------- | :------ | :------------------------------------------------------------------------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36263", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36265", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36266", "mode": "normal", "text": "\\| `continue`       | `true`  | If `false`, Claude stops processing entirely after the hook runs. Takes precedence over any event-specific decision fields |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36267", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36269", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36270", "mode": "normal", "text": "\\| `stopReason`     | none    | Message shown to the user when `continue` is `false`. Not shown to Claude                                                  |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36271", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36273", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36274", "mode": "normal", "text": "\\| `suppressOutput` | `false` | If `true`, hides stdout from verbose mode output                                                                           |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36275", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36277", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36278", "mode": "normal", "text": "\\| `systemMessage`  | none    | Warning message shown to the user                                                                                          |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36279", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36281", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36282", "mode": "normal", "text": "To stop Claude entirely regardless of event type:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36283", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36285", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36286", "mode": "normal", "text": "```json theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36287", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36289", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36290", "mode": "normal", "text": "{ \"continue\": false, \"stopReason\": \"Build failed, fix errors before continuing\" } ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36291", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36293", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36294", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36295", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36297", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36298", "mode": "normal", "text": "#### Decision control", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36299", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36301", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36302", "mode": "normal", "text": "Not every event supports blocking or controlling behavior through JSON. The events that do each use a different set of fields to express that decision. Use this table as a quick reference before writing a hook:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36303", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36305", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36306", "mode": "normal", "text": "\\| Events                                                                | Decision pattern     | Key fields                                                        |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36307", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36309", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36310", "mode": "normal", "text": "\\| :-------------------------------------------------------------------- | :------------------- | :---------------------------------------------------------------- |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36311", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36313", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36314", "mode": "normal", "text": "\\| UserPromptSubmit, PostToolUse, PostToolUseFailure, Stop, SubagentStop | Top-level `decision` | `decision: \"block\"`, `reason`                                     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36315", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36317", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36318", "mode": "normal", "text": "\\| TeammateIdle, TaskCompleted                                           | Exit code only       | Exit code 2 blocks the action, stderr is fed back as feedback     |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36319", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36321", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36322", "mode": "normal", "text": "\\| PreToolUse                                                            | `hookSpecificOutput` | `permissionDecision` (allow/deny/ask), `permissionDecisionReason` |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36323", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36325", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36326", "mode": "normal", "text": "\\| PermissionRequest                                                     | `hookSpecificOutput` | `decision.behavior` (allow/deny)                                  |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36327", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36329", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36330", "mode": "normal", "text": "Here are examples of each pattern in action:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36331", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36333", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36334", "mode": "normal", "text": "<Tabs>", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36335", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36337", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36338", "mode": "normal", "text": "  <Tab title=\"Top-level decision\">", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36339", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36341", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36342", "mode": "normal", "text": "````", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36343", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36344", "mode": "normal", "text": "Used by `UserPromptSubmit`, `PostToolUse`, `PostToolUseFailure`, `Stop`, and `SubagentStop`. The only value is `\"block\"`. To allow the action to proceed, omit `decision` from your JSON, or exit 0 without any JSON at all: ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36345", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36347", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36349", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36351", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36352", "mode": "normal", "text": "```json  theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36353", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36355", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36356", "mode": "normal", "text": "{ ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36357", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36359", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36360", "mode": "normal", "text": "  \"decision\": \"block\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36361", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36363", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36364", "mode": "normal", "text": "  \"reason\": \"Test suite must pass before proceeding\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36365", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36367", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36368", "mode": "normal", "text": "} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36369", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36371", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36372", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36373", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36374", "mode": "normal", "text": "````", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36375", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36377", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36378", "mode": "normal", "text": "  </Tab>", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36379", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36381", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36382", "mode": "normal", "text": "  <Tab title=\"PreToolUse\">", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36383", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36385", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36386", "mode": "normal", "text": "````", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36387", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36388", "mode": "normal", "text": "Uses `hookSpecificOutput` for richer control: allow, deny, or escalate to the user. You can also modify tool input before it runs or inject additional context for Claude. See [PreToolUse decision control](#pretooluse-decision-control) for the full set of options. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36389", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36391", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36393", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36395", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36396", "mode": "normal", "text": "```json  theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36397", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36399", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36400", "mode": "normal", "text": "{ ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36401", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36403", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36404", "mode": "normal", "text": "  \"hookSpecificOutput\": { ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36405", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36407", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36408", "mode": "normal", "text": "    \"hookEventName\": \"PreToolUse\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36409", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36411", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36412", "mode": "normal", "text": "    \"permissionDecision\": \"deny\", ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36413", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36415", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36416", "mode": "normal", "text": "    \"permissionDecisionReason\": \"Database writes are not allowed\" ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36417", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36419", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36420", "mode": "normal", "text": "  } ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36421", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "36423", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "36424", "mo