en": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37129", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "37130", "mode": "normal", "text": "\\| `pattern` | string | `\"**/*.ts\"`      | Glob pattern to match files against                                    |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37131", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37133", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "37134", "mode": "normal", "text": "\\| `path`    | string | `\"/path/to/dir\"` | Optional directory to search in. Defaults to current working directory |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37135", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37137", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "37138", "mode": "normal", "text": "##### Grep", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37139", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37141", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "37142", "mode": "normal", "text": "Searches file contents with regular expressions.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "37143", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"i