1, "children": [{"id": "44498", "mode": "normal", "text": "- `url`: extracts hostname from the URL", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44499", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44501", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "44502", "mode": "normal", "text": "- `npm`, `file`, `directory`: not supported for host pattern matching", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44503", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44505", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "44506", "mode": "normal", "text": "**Configuration examples**:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44507", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44509", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "44510", "mode": "normal", "text": "Example: allow specific marketplaces only:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44511", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "44513", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "44514", "mode": "normal", "text": "```json theme={null} ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle