": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"id": "3286", "mode": "normal", "text": " specific to the use case", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3287", "type": "listitem", "value": 5, "format": "", "indent": 0, "version": 1, "children": [{"id": "3288", "mode": "normal", "text": "Warn about common pitfalls", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"id": "3289", "mode": "normal", "text": " (NULL vectors, distance sign conventions)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}], "listType": "number", "direction": "ltr"}, {"id": "3290", "tag": "h3", "type": "heading", "format": "", "indent": 0, "version": 1, "children": [{"id": "3291", "mode": "normal", "text": "For Architecture Questions:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3292", "tag": "ol", "type": "list", "start": 1, "format": "", "indent": 0, "version": 1, "children": [{"id": "3293", "type": "listitem", "value": 1, "format": "", "indent": 0, "version": 1, "children": [{"id": "3294", "mode": "normal", "text": "Map requirements to appropriate index type", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"id": "3295", "mode": "normal", "text": " (HNSW vs IVFFlat)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3296", "type": "listitem", "value": 2, "format": "", "indent": 0, "version": 1, "children": [{"id": "3297", "mode": "normal", "text": "Recommend chunking strategy", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"id": "3298", "mode": "normal", "text": " based on data characteristics", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3299", "type": "listitem", "value": 3, "format": "", "indent": 0, "version": 1, "children": [{"id": "3300", "mode": "normal", "text": "Suggest retrieval pipeline", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"id": "3301", "mode": "normal", "text": " (dense → sparse → re-rank)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3302", "type": "listitem", "value": 4, "format": "", "indent": 0, "version": 1, "children": [{"id": "3303", "mode": "normal", "text": "Address scaling concerns", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"id": "3304", "mode": "normal", "text": " (partitioning, sharding, replication)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}], "listType": "number", "direction": "ltr"}, {"id": "3305", "tag": "h3", "type": "heading", "format": "", "indent": 0, "version": 1, "children": [{"id": "3306", "mode": "normal", "text": "Prohibited:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3307", "tag": "ul", "type": "list", "start": 1, "format": "", "indent": 0, "version": 1, "children": [{"id": "3308", "type": "listitem", "value": 1, "format": "", "indent": 0, "version": 1, "children": [{"id": "3309", "mode": "normal", "text": "General PostgreSQL DBA advice unrelated to vectors/graphs", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3310", "type": "listitem", "value": 2, "format": "", "indent": 0, "version": 1, "children": [{"id": "3311", "mode": "normal", "text": "Specific cloud vendor recommendations", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3312", "type": "listitem", "value": 3, "format": "", "indent": 0, "version": 1, "children": [{"id": "3313", "mode": "normal", "text": "Writing full application implementations", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3314", "type": "listitem", "value": 4, "format": "", "indent": 0, "version": 1, "children": [{"id": "3315", "mode": "normal", "text": "Creating actual embeddings or performing live vector operations", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}], "listType": "bullet", "direction": "ltr"}, {"id": "3316", "tag": "h3", "type": "heading", "format": "", "indent": 0, "version": 1, "children": [{"id": "3317", "mode": "normal", "text": "Citation Format:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3318", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "3319", "mode": "normal", "text": "When referencing algorithms or research, cite key papers:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"id": "3320", "tag": "ul", "type": "list", "start": 1, "format": "", "indent": 0, "version": 1, "children": [{"id": "3321", "type": "listitem", "value": 1, "format": "", "indent": 0, "version": 1, "children": [{"id": "3322", "mode": "normal", "text": "HNSW: \"Efficient and Robust Approximate Nearest Neighbor Search using Hierarchical Navigable Small World Graphs\" (Malkov & Yashunin)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3323", "type": "listitem", "value": 2, "format": "", "indent": 0, "version": 1, "children": [{"id": "3324", "mode": "normal", "text": "RAG: \"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks\" (Lewis et al., NeurIPS 2020)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}, {"id": "3325", "type": "listitem", "value": 3, "format": "", "indent": 0, "version": 1, "children": [{"id": "3326", "mode": "normal", "text": "IVFFlat: Based on Faiss library (Facebook Research)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr"}], "listType": "bullet", "direction": "ltr"}, {"id": "3330", "type": "horizontalrule", "version": 1}, {"id": "5582", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "3331", "mode": "normal", "text": "# pgvector", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3332", "type": "linebreak", "version": 1}, {"id": "3333", "type": "linebreak", "version": 1}, {"id": "3334", "mode": "normal", "text": "Open-source vector similarity search for Postgres", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3335", "type": "linebreak", "version": 1}, {"id": "3336", "type": "linebreak", "version": 1}, {"id": "3337", "mode": "normal", "text": "Store your vectors with the rest of your data. Supports:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3338", "type": "linebreak", "version": 1}, {"id": "3339", "type": "linebreak", "version": 1}, {"id": "3340", "mode": "normal", "text": "- exact and approximate nearest neighbor search", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3341", "type": "linebreak", "version": 1}, {"id": "3342", "mode": "normal", "text": "- single-precision, half-precision, binary, and sparse vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3343", "type": "linebreak", "version": 1}, {"id": "3344", "mode": "normal", "text": "- L2 distance, inner product, cosine distance, L1 distance, Hamming distance, and Jaccard distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3345", "type": "linebreak", "version": 1}, {"id": "3346", "mode": "normal", "text": "- any [language](#languages) with a Postgres client", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3347", "type": "linebreak", "version": 1}, {"id": "3348", "type": "linebreak", "version": 1}, {"id": "3349", "mode": "normal", "text": "Plus [ACID](https://en.wikipedia.org/wiki/ACID) compliance, point-in-time recovery, JOINs, and all of the other [great features](https://www.postgresql.org/about/) of Postgres", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3350", "type": "linebreak", "version": 1}, {"id": "3351", "type": "linebreak", "version": 1}, {"id": "3352", "mode": "normal", "text": "[![Build Status](https://github.com/pgvector/pgvector/actions/workflows/build.yml/badge.svg)](https://github.com/pgvector/pgvector/actions)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3353", "type": "linebreak", "version": 1}, {"id": "3354", "type": "linebreak", "version": 1}, {"id": "3355", "mode": "normal", "text": "## Installation", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3356", "type": "linebreak", "version": 1}, {"id": "3357", "type": "linebreak", "version": 1}, {"id": "3358", "mode": "normal", "text": "### Linux and Mac", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3359", "type": "linebreak", "version": 1}, {"id": "3360", "type": "linebreak", "version": 1}, {"id": "3361", "mode": "normal", "text": "Compile and install the extension (supports Postgres 13+)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3362", "type": "linebreak", "version": 1}, {"id": "3363", "type": "linebreak", "version": 1}, {"id": "3364", "mode": "normal", "text": "```sh", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3365", "type": "linebreak", "version": 1}, {"id": "3366", "mode": "normal", "text": "cd /tmp", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3367", "type": "linebreak", "version": 1}, {"id": "3368", "mode": "normal", "text": "git clone --branch v0.8.2 https://github.com/pgvector/pgvector.git", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3369", "type": "linebreak", "version": 1}, {"id": "3370", "mode": "normal", "text": "cd pgvector", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3371", "type": "linebreak", "version": 1}, {"id": "3372", "mode": "normal", "text": "make", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3373", "type": "linebreak", "version": 1}, {"id": "3374", "mode": "normal", "text": "make install # may need sudo", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3375", "type": "linebreak", "version": 1}, {"id": "3376", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3377", "type": "linebreak", "version": 1}, {"id": "3378", "type": "linebreak", "version": 1}, {"id": "3379", "mode": "normal", "text": "See the [installation notes](#installation-notes---linux-and-mac) if you run into issues", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3380", "type": "linebreak", "version": 1}, {"id": "3381", "type": "linebreak", "version": 1}, {"id": "3382", "mode": "normal", "text": "You can also install it with [Docker](#docker), [Homebrew](#homebrew), [PGXN](#pgxn), [APT](#apt), [Yum](#yum), [pkg](#pkg), [APK](#apk), or [conda-forge](#conda-forge), and it comes preinstalled with [Postgres.app](#postgresapp) and many [hosted providers](#hosted-postgres). There are also instructions for [GitHub Actions](https://github.com/pgvector/setup-pgvector).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3383", "type": "linebreak", "version": 1}, {"id": "3384", "type": "linebreak", "version": 1}, {"id": "3385", "mode": "normal", "text": "### Windows", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3386", "type": "linebreak", "version": 1}, {"id": "3387", "type": "linebreak", "version": 1}, {"id": "3388", "mode": "normal", "text": "Ensure [C++ support in Visual Studio](https://learn.microsoft.com/en-us/cpp/build/building-on-the-command-line?view=msvc-170#download-and-install-the-tools) is installed and run `x64 Native Tools Command Prompt for VS [version]` as administrator. Then use `nmake` to build:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3389", "type": "linebreak", "version": 1}, {"id": "3390", "type": "linebreak", "version": 1}, {"id": "3391", "mode": "normal", "text": "```cmd", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3392", "type": "linebreak", "version": 1}, {"id": "3393", "mode": "normal", "text": "set \"PGROOT=C:\\Program Files\\PostgreSQL\\18\"", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3394", "type": "linebreak", "version": 1}, {"id": "3395", "mode": "normal", "text": "cd %TEMP%", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3396", "type": "linebreak", "version": 1}, {"id": "3397", "mode": "normal", "text": "git clone --branch v0.8.2 https://github.com/pgvector/pgvector.git", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3398", "type": "linebreak", "version": 1}, {"id": "3399", "mode": "normal", "text": "cd pgvector", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3400", "type": "linebreak", "version": 1}, {"id": "3401", "mode": "normal", "text": "nmake /F Makefile.win", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3402", "type": "linebreak", "version": 1}, {"id": "3403", "mode": "normal", "text": "nmake /F Makefile.win install", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3404", "type": "linebreak", "version": 1}, {"id": "3405", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3406", "type": "linebreak", "version": 1}, {"id": "3407", "type": "linebreak", "version": 1}, {"id": "3408", "mode": "normal", "text": "See the [installation notes](#installation-notes---windows) if you run into issues", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3409", "type": "linebreak", "version": 1}, {"id": "3410", "type": "linebreak", "version": 1}, {"id": "3411", "mode": "normal", "text": "You can also install it with [Docker](#docker) or [conda-forge](#conda-forge).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3412", "type": "linebreak", "version": 1}, {"id": "3413", "type": "linebreak", "version": 1}, {"id": "3414", "mode": "normal", "text": "## Getting Started", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3415", "type": "linebreak", "version": 1}, {"id": "3416", "type": "linebreak", "version": 1}, {"id": "3417", "mode": "normal", "text": "Enable the extension (do this once in each database where you want to use it)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3418", "type": "linebreak", "version": 1}, {"id": "3419", "type": "linebreak", "version": 1}, {"id": "3420", "mode": "normal", "text": "```tsql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3421", "type": "linebreak", "version": 1}, {"id": "3422", "mode": "normal", "text": "CREATE EXTENSION vector;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3423", "type": "linebreak", "version": 1}, {"id": "3424", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3425", "type": "linebreak", "version": 1}, {"id": "3426", "type": "linebreak", "version": 1}, {"id": "3427", "mode": "normal", "text": "Create a vector column with 3 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3428", "type": "linebreak", "version": 1}, {"id": "3429", "type": "linebreak", "version": 1}, {"id": "3430", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3431", "type": "linebreak", "version": 1}, {"id": "3432", "mode": "normal", "text": "CREATE TABLE items (id bigserial PRIMARY KEY, embedding vector(3));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3433", "type": "linebreak", "version": 1}, {"id": "3434", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3435", "type": "linebreak", "version": 1}, {"id": "3436", "type": "linebreak", "version": 1}, {"id": "3437", "mode": "normal", "text": "Insert vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3438", "type": "linebreak", "version": 1}, {"id": "3439", "type": "linebreak", "version": 1}, {"id": "3440", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3441", "type": "linebreak", "version": 1}, {"id": "3442", "mode": "normal", "text": "INSERT INTO items (embedding) VALUES (''[1,2,3]''), (''[4,5,6]'');", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3443", "type": "linebreak", "version": 1}, {"id": "3444", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3445", "type": "linebreak", "version": 1}, {"id": "3446", "type": "linebreak", "version": 1}, {"id": "3447", "mode": "normal", "text": "Get the nearest neighbors by L2 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3448", "type": "linebreak", "version": 1}, {"id": "3449", "type": "linebreak", "version": 1}, {"id": "3450", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3451", "type": "linebreak", "version": 1}, {"id": "3452", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding <-> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3453", "type": "linebreak", "version": 1}, {"id": "3454", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3455", "type": "linebreak", "version": 1}, {"id": "3456", "type": "linebreak", "version": 1}, {"id": "3457", "mode": "normal", "text": "Also supports inner product (`<#>`), cosine distance (`<=>`), and L1 distance (`<+>`)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3458", "type": "linebreak", "version": 1}, {"id": "3459", "type": "linebreak", "version": 1}, {"id": "3460", "mode": "normal", "text": "Note: `<#>` returns the negative inner product since Postgres only supports `ASC` order index scans on operators", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3461", "type": "linebreak", "version": 1}, {"id": "3462", "type": "linebreak", "version": 1}, {"id": "3463", "mode": "normal", "text": "## Storing", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3464", "type": "linebreak", "version": 1}, {"id": "3465", "type": "linebreak", "version": 1}, {"id": "3466", "mode": "normal", "text": "Create a new table with a vector column", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3467", "type": "linebreak", "version": 1}, {"id": "3468", "type": "linebreak", "version": 1}, {"id": "3469", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3470", "type": "linebreak", "version": 1}, {"id": "3471", "mode": "normal", "text": "CREATE TABLE items (id bigserial PRIMARY KEY, embedding vector(3));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3472", "type": "linebreak", "version": 1}, {"id": "3473", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3474", "type": "linebreak", "version": 1}, {"id": "3475", "type": "linebreak", "version": 1}, {"id": "3476", "mode": "normal", "text": "Or add a vector column to an existing table", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3477", "type": "linebreak", "version": 1}, {"id": "3478", "type": "linebreak", "version": 1}, {"id": "3479", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3480", "type": "linebreak", "version": 1}, {"id": "3481", "mode": "normal", "text": "ALTER TABLE items ADD COLUMN embedding vector(3);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3482", "type": "linebreak", "version": 1}, {"id": "3483", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3484", "type": "linebreak", "version": 1}, {"id": "3485", "type": "linebreak", "version": 1}, {"id": "3486", "mode": "normal", "text": "Also supports [half-precision](#half-precision-vectors), [binary](#binary-vectors), and [sparse](#sparse-vectors) vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3487", "type": "linebreak", "version": 1}, {"id": "3488", "type": "linebreak", "version": 1}, {"id": "3489", "mode": "normal", "text": "Insert vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3490", "type": "linebreak", "version": 1}, {"id": "3491", "type": "linebreak", "version": 1}, {"id": "3492", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3493", "type": "linebreak", "version": 1}, {"id": "3494", "mode": "normal", "text": "INSERT INTO items (embedding) VALUES (''[1,2,3]''), (''[4,5,6]'');", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3495", "type": "linebreak", "version": 1}, {"id": "3496", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3497", "type": "linebreak", "version": 1}, {"id": "3498", "type": "linebreak", "version": 1}, {"id": "3499", "mode": "normal", "text": "Or load vectors in bulk using `COPY` ([example](https://github.com/pgvector/pgvector-python/blob/master/examples/loading/example.py))", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3500", "type": "linebreak", "version": 1}, {"id": "3501", "type": "linebreak", "version": 1}, {"id": "3502", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3503", "type": "linebreak", "version": 1}, {"id": "3504", "mode": "normal", "text": "COPY items (embedding) FROM STDIN WITH (FORMAT BINARY);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3505", "type": "linebreak", "version": 1}, {"id": "3506", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3507", "type": "linebreak", "version": 1}, {"id": "3508", "type": "linebreak", "version": 1}, {"id": "3509", "mode": "normal", "text": "Upsert vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3510", "type": "linebreak", "version": 1}, {"id": "3511", "type": "linebreak", "version": 1}, {"id": "3512", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3513", "type": "linebreak", "version": 1}, {"id": "3514", "mode": "normal", "text": "INSERT INTO items (id, embedding) VALUES (1, ''[1,2,3]''), (2, ''[4,5,6]'')", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3515", "type": "linebreak", "version": 1}, {"id": "3516", "mode": "normal", "text": "    ON CONFLICT (id) DO UPDATE SET embedding = EXCLUDED.embedding;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3517", "type": "linebreak", "version": 1}, {"id": "3518", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3519", "type": "linebreak", "version": 1}, {"id": "3520", "type": "linebreak", "version": 1}, {"id": "3521", "mode": "normal", "text": "Update vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3522", "type": "linebreak", "version": 1}, {"id": "3523", "type": "linebreak", "version": 1}, {"id": "3524", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3525", "type": "linebreak", "version": 1}, {"id": "3526", "mode": "normal", "text": "UPDATE items SET embedding = ''[1,2,3]'' WHERE id = 1;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3527", "type": "linebreak", "version": 1}, {"id": "3528", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3529", "type": "linebreak", "version": 1}, {"id": "3530", "type": "linebreak", "version": 1}, {"id": "3531", "mode": "normal", "text": "Delete vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3532", "type": "linebreak", "version": 1}, {"id": "3533", "type": "linebreak", "version": 1}, {"id": "3534", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3535", "type": "linebreak", "version": 1}, {"id": "3536", "mode": "normal", "text": "DELETE FROM items WHERE id = 1;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3537", "type": "linebreak", "version": 1}, {"id": "3538", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3539", "type": "linebreak", "version": 1}, {"id": "3540", "type": "linebreak", "version": 1}, {"id": "3541", "mode": "normal", "text": "## Querying", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3542", "type": "linebreak", "version": 1}, {"id": "3543", "type": "linebreak", "version": 1}, {"id": "3544", "mode": "normal", "text": "Get the nearest neighbors to a vector", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3545", "type": "linebreak", "version": 1}, {"id": "3546", "type": "linebreak", "version": 1}, {"id": "3547", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3548", "type": "linebreak", "version": 1}, {"id": "3549", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding <-> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3550", "type": "linebreak", "version": 1}, {"id": "3551", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3552", "type": "linebreak", "version": 1}, {"id": "3553", "type": "linebreak", "version": 1}, {"id": "3554", "mode": "normal", "text": "Supported distance functions are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3555", "type": "linebreak", "version": 1}, {"id": "3556", "type": "linebreak", "version": 1}, {"id": "3557", "mode": "normal", "text": "- `<->` - L2 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3558", "type": "linebreak", "version": 1}, {"id": "3559", "mode": "normal", "text": "- `<#>` - (negative) inner product", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3560", "type": "linebreak", "version": 1}, {"id": "3561", "mode": "normal", "text": "- `<=>` - cosine distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3562", "type": "linebreak", "version": 1}, {"id": "3563", "mode": "normal", "text": "- `<+>` - L1 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3564", "type": "linebreak", "version": 1}, {"id": "3565", "mode": "normal", "text": "- `<~>` - Hamming distance (binary vectors)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3566", "type": "linebreak", "version": 1}, {"id": "3567", "mode": "normal", "text": "- `<%>` - Jaccard distance (binary vectors)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3568", "type": "linebreak", "version": 1}, {"id": "3569", "type": "linebreak", "version": 1}, {"id": "3570", "mode": "normal", "text": "Get the nearest neighbors to a row", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3571", "type": "linebreak", "version": 1}, {"id": "3572", "type": "linebreak", "version": 1}, {"id": "3573", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3574", "type": "linebreak", "version": 1}, {"id": "3575", "mode": "normal", "text": "SELECT * FROM items WHERE id != 1 ORDER BY embedding <-> (SELECT embedding FROM items WHERE id = 1) LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3576", "type": "linebreak", "version": 1}, {"id": "3577", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3578", "type": "linebreak", "version": 1}, {"id": "3579", "type": "linebreak", "version": 1}, {"id": "3580", "mode": "normal", "text": "Get rows within a certain distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3581", "type": "linebreak", "version": 1}, {"id": "3582", "type": "linebreak", "version": 1}, {"id": "3583", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3584", "type": "linebreak", "version": 1}, {"id": "3585", "mode": "normal", "text": "SELECT * FROM items WHERE embedding <-> ''[3,1,2]'' < 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3586", "type": "linebreak", "version": 1}, {"id": "3587", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3588", "type": "linebreak", "version": 1}, {"id": "3589", "type": "linebreak", "version": 1}, {"id": "3590", "mode": "normal", "text": "Note: Combine with `ORDER BY` and `LIMIT` to use an index", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3591", "type": "linebreak", "version": 1}, {"id": "3592", "type": "linebreak", "version": 1}, {"id": "3593", "mode": "normal", "text": "#### Distances", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3594", "type": "linebreak", "version": 1}, {"id": "3595", "type": "linebreak", "version": 1}, {"id": "3596", "mode": "normal", "text": "Get the distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3597", "type": "linebreak", "version": 1}, {"id": "3598", "type": "linebreak", "version": 1}, {"id": "3599", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3600", "type": "linebreak", "version": 1}, {"id": "3601", "mode": "normal", "text": "SELECT embedding <-> ''[3,1,2]'' AS distance FROM items;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3602", "type": "linebreak", "version": 1}, {"id": "3603", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3604", "type": "linebreak", "version": 1}, {"id": "3605", "type": "linebreak", "version": 1}, {"id": "3606", "mode": "normal", "text": "For inner product, multiply by -1 (since `<#>` returns the negative inner product)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3607", "type": "linebreak", "version": 1}, {"id": "3608", "type": "linebreak", "version": 1}, {"id": "3609", "mode": "normal", "text": "```tsql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3610", "type": "linebreak", "version": 1}, {"id": "3611", "mode": "normal", "text": "SELECT (embedding <#> ''[3,1,2]'') * -1 AS inner_product FROM items;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3612", "type": "linebreak", "version": 1}, {"id": "3613", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3614", "type": "linebreak", "version": 1}, {"id": "3615", "type": "linebreak", "version": 1}, {"id": "3616", "mode": "normal", "text": "For cosine similarity, use 1 - cosine distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3617", "type": "linebreak", "version": 1}, {"id": "3618", "type": "linebreak", "version": 1}, {"id": "3619", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3620", "type": "linebreak", "version": 1}, {"id": "3621", "mode": "normal", "text": "SELECT 1 - (embedding <=> ''[3,1,2]'') AS cosine_similarity FROM items;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3622", "type": "linebreak", "version": 1}, {"id": "3623", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3624", "type": "linebreak", "version": 1}, {"id": "3625", "type": "linebreak", "version": 1}, {"id": "3626", "mode": "normal", "text": "#### Aggregates", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3627", "type": "linebreak", "version": 1}, {"id": "3628", "type": "linebreak", "version": 1}, {"id": "3629", "mode": "normal", "text": "Average vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3630", "type": "linebreak", "version": 1}, {"id": "3631", "type": "linebreak", "version": 1}, {"id": "3632", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3633", "type": "linebreak", "version": 1}, {"id": "3634", "mode": "normal", "text": "SELECT AVG(embedding) FROM items;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3635", "type": "linebreak", "version": 1}, {"id": "3636", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3637", "type": "linebreak", "version": 1}, {"id": "3638", "type": "linebreak", "version": 1}, {"id": "3639", "mode": "normal", "text": "Average groups of vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3640", "type": "linebreak", "version": 1}, {"id": "3641", "type": "linebreak", "version": 1}, {"id": "3642", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3643", "type": "linebreak", "version": 1}, {"id": "3644", "mode": "normal", "text": "SELECT category_id, AVG(embedding) FROM items GROUP BY category_id;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3645", "type": "linebreak", "version": 1}, {"id": "3646", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3647", "type": "linebreak", "version": 1}, {"id": "3648", "type": "linebreak", "version": 1}, {"id": "3649", "mode": "normal", "text": "## Indexing", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3650", "type": "linebreak", "version": 1}, {"id": "3651", "type": "linebreak", "version": 1}, {"id": "3652", "mode": "normal", "text": "By default, pgvector performs exact nearest neighbor search, which provides perfect recall.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3653", "type": "linebreak", "version": 1}, {"id": "3654", "type": "linebreak", "version": 1}, {"id": "3655", "mode": "normal", "text": "You can add an index to use approximate nearest neighbor search, which trades some recall for speed. Unlike typical indexes, you will see different results for queries after adding an approximate index.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3656", "type": "linebreak", "version": 1}, {"id": "3657", "type": "linebreak", "version": 1}, {"id": "3658", "mode": "normal", "text": "Supported index types are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3659", "type": "linebreak", "version": 1}, {"id": "3660", "type": "linebreak", "version": 1}, {"id": "3661", "mode": "normal", "text": "- [HNSW](#hnsw)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3662", "type": "linebreak", "version": 1}, {"id": "3663", "mode": "normal", "text": "- [IVFFlat](#ivfflat)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3664", "type": "linebreak", "version": 1}, {"id": "3665", "type": "linebreak", "version": 1}, {"id": "3666", "mode": "normal", "text": "## HNSW", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3667", "type": "linebreak", "version": 1}, {"id": "3668", "type": "linebreak", "version": 1}, {"id": "3669", "mode": "normal", "text": "An HNSW index creates a multilayer graph. It has better query performance than IVFFlat (in terms of speed-recall tradeoff), but has slower build times and uses more memory. Also, an index can be created without any data in the table since there isn’t a training step like IVFFlat.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3670", "type": "linebreak", "version": 1}, {"id": "3671", "type": "linebreak", "version": 1}, {"id": "3672", "mode": "normal", "text": "Add an index for each distance function you want to use.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3673", "type": "linebreak", "version": 1}, {"id": "3674", "type": "linebreak", "version": 1}, {"id": "3675", "mode": "normal", "text": "L2 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3676", "type": "linebreak", "version": 1}, {"id": "3677", "type": "linebreak", "version": 1}, {"id": "3678", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3679", "type": "linebreak", "version": 1}, {"id": "3680", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_l2_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3681", "type": "linebreak", "version": 1}, {"id": "3682", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3683", "type": "linebreak", "version": 1}, {"id": "3684", "type": "linebreak", "version": 1}, {"id": "3685", "mode": "normal", "text": "Note: Use `halfvec_l2_ops` for `halfvec` and `sparsevec_l2_ops` for `sparsevec` (and similar with the other distance functions)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3686", "type": "linebreak", "version": 1}, {"id": "3687", "type": "linebreak", "version": 1}, {"id": "3688", "mode": "normal", "text": "Inner product", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3689", "type": "linebreak", "version": 1}, {"id": "3690", "type": "linebreak", "version": 1}, {"id": "3691", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3692", "type": "linebreak", "version": 1}, {"id": "3693", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_ip_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3694", "type": "linebreak", "version": 1}, {"id": "3695", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3696", "type": "linebreak", "version": 1}, {"id": "3697", "type": "linebreak", "version": 1}, {"id": "3698", "mode": "normal", "text": "Cosine distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3699", "type": "linebreak", "version": 1}, {"id": "3700", "type": "linebreak", "version": 1}, {"id": "3701", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3702", "type": "linebreak", "version": 1}, {"id": "3703", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_cosine_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3704", "type": "linebreak", "version": 1}, {"id": "3705", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3706", "type": "linebreak", "version": 1}, {"id": "3707", "type": "linebreak", "version": 1}, {"id": "3708", "mode": "normal", "text": "L1 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3709", "type": "linebreak", "version": 1}, {"id": "3710", "type": "linebreak", "version": 1}, {"id": "3711", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3712", "type": "linebreak", "version": 1}, {"id": "3713", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_l1_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3714", "type": "linebreak", "version": 1}, {"id": "3715", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3716", "type": "linebreak", "version": 1}, {"id": "3717", "type": "linebreak", "version": 1}, {"id": "3718", "mode": "normal", "text": "Hamming distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3719", "type": "linebreak", "version": 1}, {"id": "3720", "type": "linebreak", "version": 1}, {"id": "3721", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3722", "type": "linebreak", "version": 1}, {"id": "3723", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding bit_hamming_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3724", "type": "linebreak", "version": 1}, {"id": "3725", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3726", "type": "linebreak", "version": 1}, {"id": "3727", "type": "linebreak", "version": 1}, {"id": "3728", "mode": "normal", "text": "Jaccard distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3729", "type": "linebreak", "version": 1}, {"id": "3730", "type": "linebreak", "version": 1}, {"id": "3731", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3732", "type": "linebreak", "version": 1}, {"id": "3733", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding bit_jaccard_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3734", "type": "linebreak", "version": 1}, {"id": "3735", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3736", "type": "linebreak", "version": 1}, {"id": "3737", "type": "linebreak", "version": 1}, {"id": "3738", "mode": "normal", "text": "Supported types are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3739", "type": "linebreak", "version": 1}, {"id": "3740", "type": "linebreak", "version": 1}, {"id": "3741", "mode": "normal", "text": "- `vector` - up to 2,000 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3742", "type": "linebreak", "version": 1}, {"id": "3743", "mode": "normal", "text": "- `halfvec` - up to 4,000 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3744", "type": "linebreak", "version": 1}, {"id": "3745", "mode": "normal", "text": "- `bit` - up to 64,000 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3746", "type": "linebreak", "version": 1}, {"id": "3747", "mode": "normal", "text": "- `sparsevec` - up to 1,000 non-zero elements", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3748", "type": "linebreak", "version": 1}, {"id": "3749", "type": "linebreak", "version": 1}, {"id": "3750", "mode": "normal", "text": "### Index Options", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3751", "type": "linebreak", "version": 1}, {"id": "3752", "type": "linebreak", "version": 1}, {"id": "3753", "mode": "normal", "text": "Specify HNSW parameters", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3754", "type": "linebreak", "version": 1}, {"id": "3755", "type": "linebreak", "version": 1}, {"id": "3756", "mode": "normal", "text": "- `m` - the max number of connections per layer (16 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3757", "type": "linebreak", "version": 1}, {"id": "3758", "mode": "normal", "text": "- `ef_construction` - the size of the dynamic candidate list for constructing the graph (64 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3759", "type": "linebreak", "version": 1}, {"id": "3760", "type": "linebreak", "version": 1}, {"id": "3761", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3762", "type": "linebreak", "version": 1}, {"id": "3763", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_l2_ops) WITH (m = 16, ef_construction = 64);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3764", "type": "linebreak", "version": 1}, {"id": "3765", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3766", "type": "linebreak", "version": 1}, {"id": "3767", "type": "linebreak", "version": 1}, {"id": "3768", "mode": "normal", "text": "A higher value of `ef_construction` provides better recall at the cost of index build time / insert speed.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3769", "type": "linebreak", "version": 1}, {"id": "3770", "type": "linebreak", "version": 1}, {"id": "3771", "mode": "normal", "text": "### Query Options", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3772", "type": "linebreak", "version": 1}, {"id": "3773", "type": "linebreak", "version": 1}, {"id": "3774", "mode": "normal", "text": "Specify the size of the dynamic candidate list for search (40 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3775", "type": "linebreak", "version": 1}, {"id": "3776", "type": "linebreak", "version": 1}, {"id": "3777", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3778", "type": "linebreak", "version": 1}, {"id": "3779", "mode": "normal", "text": "SET hnsw.ef_search = 100;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3780", "type": "linebreak", "version": 1}, {"id": "3781", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3782", "type": "linebreak", "version": 1}, {"id": "3783", "type": "linebreak", "version": 1}, {"id": "3784", "mode": "normal", "text": "A higher value provides better recall at the cost of speed.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3785", "type": "linebreak", "version": 1}, {"id": "3786", "type": "linebreak", "version": 1}, {"id": "3787", "mode": "normal", "text": "Use `SET LOCAL` inside a transaction to set it for a single query", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3788", "type": "linebreak", "version": 1}, {"id": "3789", "type": "linebreak", "version": 1}, {"id": "3790", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3791", "type": "linebreak", "version": 1}, {"id": "3792", "mode": "normal", "text": "BEGIN;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3793", "type": "linebreak", "version": 1}, {"id": "3794", "mode": "normal", "text": "SET LOCAL hnsw.ef_search = 100;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3795", "type": "linebreak", "version": 1}, {"id": "3796", "mode": "normal", "text": "SELECT ...", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3797", "type": "linebreak", "version": 1}, {"id": "3798", "mode": "normal", "text": "COMMIT;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3799", "type": "linebreak", "version": 1}, {"id": "3800", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3801", "type": "linebreak", "version": 1}, {"id": "3802", "type": "linebreak", "version": 1}, {"id": "3803", "mode": "normal", "text": "### Index Build Time", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3804", "type": "linebreak", "version": 1}, {"id": "3805", "type": "linebreak", "version": 1}, {"id": "3806", "mode": "normal", "text": "Indexes build significantly faster when the graph fits into `maintenance_work_mem`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3807", "type": "linebreak", "version": 1}, {"id": "3808", "type": "linebreak", "version": 1}, {"id": "3809", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3810", "type": "linebreak", "version": 1}, {"id": "3811", "mode": "normal", "text": "SET maintenance_work_mem = ''8GB'';", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3812", "type": "linebreak", "version": 1}, {"id": "3813", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3814", "type": "linebreak", "version": 1}, {"id": "3815", "type": "linebreak", "version": 1}, {"id": "3816", "mode": "normal", "text": "A notice is shown when the graph no longer fits", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3817", "type": "linebreak", "version": 1}, {"id": "3818", "type": "linebreak", "version": 1}, {"id": "3819", "mode": "normal", "text": "```text", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3820", "type": "linebreak", "version": 1}, {"id": "3821", "mode": "normal", "text": "NOTICE:  hnsw graph no longer fits into maintenance_work_mem after 100000 tuples", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3822", "type": "linebreak", "version": 1}, {"id": "3823", "mode": "normal", "text": "DETAIL:  Building will take significantly more time.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3824", "type": "linebreak", "version": 1}, {"id": "3825", "mode": "normal", "text": "HINT:  Increase maintenance_work_mem to speed up builds.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3826", "type": "linebreak", "version": 1}, {"id": "3827", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3828", "type": "linebreak", "version": 1}, {"id": "3829", "type": "linebreak", "version": 1}, {"id": "3830", "mode": "normal", "text": "Note: Do not set `maintenance_work_mem` so high that it exhausts the memory on the server", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3831", "type": "linebreak", "version": 1}, {"id": "3832", "type": "linebreak", "version": 1}, {"id": "3833", "mode": "normal", "text": "Like other index types, it’s faster to create an index after loading your initial data", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3834", "type": "linebreak", "version": 1}, {"id": "3835", "type": "linebreak", "version": 1}, {"id": "3836", "mode": "normal", "text": "You can also speed up index creation by increasing the number of parallel workers (2 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3837", "type": "linebreak", "version": 1}, {"id": "3838", "type": "linebreak", "version": 1}, {"id": "3839", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3840", "type": "linebreak", "version": 1}, {"id": "3841", "mode": "normal", "text": "SET max_parallel_maintenance_workers = 7; -- plus leader", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3842", "type": "linebreak", "version": 1}, {"id": "3843", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3844", "type": "linebreak", "version": 1}, {"id": "3845", "type": "linebreak", "version": 1}, {"id": "3846", "mode": "normal", "text": "For a large number of workers, you may need to increase `max_parallel_workers` (8 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3847", "type": "linebreak", "version": 1}, {"id": "3848", "type": "linebreak", "version": 1}, {"id": "3849", "mode": "normal", "text": "The [index options](#index-options) also have a significant impact on build time (use the defaults unless seeing low recall)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3850", "type": "linebreak", "version": 1}, {"id": "3851", "type": "linebreak", "version": 1}, {"id": "3852", "mode": "normal", "text": "### Indexing Progress", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3853", "type": "linebreak", "version": 1}, {"id": "3854", "type": "linebreak", "version": 1}, {"id": "3855", "mode": "normal", "text": "Check [indexing progress](https://www.postgresql.org/docs/current/progress-reporting.html#CREATE-INDEX-PROGRESS-REPORTING)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3856", "type": "linebreak", "version": 1}, {"id": "3857", "type": "linebreak", "version": 1}, {"id": "3858", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3859", "type": "linebreak", "version": 1}, {"id": "3860", "mode": "normal", "text": "SELECT phase, round(100.0 * blocks_done / nullif(blocks_total, 0), 1) AS \"%\" FROM pg_stat_progress_create_index;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3861", "type": "linebreak", "version": 1}, {"id": "3862", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3863", "type": "linebreak", "version": 1}, {"id": "3864", "type": "linebreak", "version": 1}, {"id": "3865", "mode": "normal", "text": "The phases for HNSW are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3866", "type": "linebreak", "version": 1}, {"id": "3867", "type": "linebreak", "version": 1}, {"id": "3868", "mode": "normal", "text": "1. `initializing`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3869", "type": "linebreak", "version": 1}, {"id": "3870", "mode": "normal", "text": "2. `loading tuples`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3871", "type": "linebreak", "version": 1}, {"id": "3872", "type": "linebreak", "version": 1}, {"id": "3873", "mode": "normal", "text": "## IVFFlat", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3874", "type": "linebreak", "version": 1}, {"id": "3875", "type": "linebreak", "version": 1}, {"id": "3876", "mode": "normal", "text": "An IVFFlat index divides vectors into lists, and then searches a subset of those lists that are closest to the query vector. It has faster build times and uses less memory than HNSW, but has lower query performance (in terms of speed-recall tradeoff).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3877", "type": "linebreak", "version": 1}, {"id": "3878", "type": "linebreak", "version": 1}, {"id": "3879", "mode": "normal", "text": "Three keys to achieving good recall are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3880", "type": "linebreak", "version": 1}, {"id": "3881", "type": "linebreak", "version": 1}, {"id": "3882", "mode": "normal", "text": "1. Create the index *after* the table has some data", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3883", "type": "linebreak", "version": 1}, {"id": "3884", "mode": "normal", "text": "2. Choose an appropriate number of lists - a good place to start is `rows / 1000` for up to 1M rows and `sqrt(rows)` for over 1M rows", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3885", "type": "linebreak", "version": 1}, {"id": "3886", "mode": "normal", "text": "3. When querying, specify an appropriate number of [probes](#query-options) (higher is better for recall, lower is better for speed) - a good place to start is `sqrt(lists)`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3887", "type": "linebreak", "version": 1}, {"id": "3888", "type": "linebreak", "version": 1}, {"id": "3889", "mode": "normal", "text": "Add an index for each distance function you want to use.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3890", "type": "linebreak", "version": 1}, {"id": "3891", "type": "linebreak", "version": 1}, {"id": "3892", "mode": "normal", "text": "L2 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3893", "type": "linebreak", "version": 1}, {"id": "3894", "type": "linebreak", "version": 1}, {"id": "3895", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3896", "type": "linebreak", "version": 1}, {"id": "3897", "mode": "normal", "text": "CREATE INDEX ON items USING ivfflat (embedding vector_l2_ops) WITH (lists = 100);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3898", "type": "linebreak", "version": 1}, {"id": "3899", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3900", "type": "linebreak", "version": 1}, {"id": "3901", "type": "linebreak", "version": 1}, {"id": "3902", "mode": "normal", "text": "Note: Use `halfvec_l2_ops` for `halfvec` (and similar with the other distance functions)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3903", "type": "linebreak", "version": 1}, {"id": "3904", "type": "linebreak", "version": 1}, {"id": "3905", "mode": "normal", "text": "Inner product", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3906", "type": "linebreak", "version": 1}, {"id": "3907", "type": "linebreak", "version": 1}, {"id": "3908", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3909", "type": "linebreak", "version": 1}, {"id": "3910", "mode": "normal", "text": "CREATE INDEX ON items USING ivfflat (embedding vector_ip_ops) WITH (lists = 100);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3911", "type": "linebreak", "version": 1}, {"id": "3912", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3913", "type": "linebreak", "version": 1}, {"id": "3914", "type": "linebreak", "version": 1}, {"id": "3915", "mode": "normal", "text": "Cosine distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3916", "type": "linebreak", "version": 1}, {"id": "3917", "type": "linebreak", "version": 1}, {"id": "3918", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3919", "type": "linebreak", "version": 1}, {"id": "3920", "mode": "normal", "text": "CREATE INDEX ON items USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3921", "type": "linebreak", "version": 1}, {"id": "3922", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3923", "type": "linebreak", "version": 1}, {"id": "3924", "type": "linebreak", "version": 1}, {"id": "3925", "mode": "normal", "text": "Hamming distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3926", "type": "linebreak", "version": 1}, {"id": "3927", "type": "linebreak", "version": 1}, {"id": "3928", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3929", "type": "linebreak", "version": 1}, {"id": "3930", "mode": "normal", "text": "CREATE INDEX ON items USING ivfflat (embedding bit_hamming_ops) WITH (lists = 100);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3931", "type": "linebreak", "version": 1}, {"id": "3932", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3933", "type": "linebreak", "version": 1}, {"id": "3934", "type": "linebreak", "version": 1}, {"id": "3935", "mode": "normal", "text": "Supported types are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3936", "type": "linebreak", "version": 1}, {"id": "3937", "type": "linebreak", "version": 1}, {"id": "3938", "mode": "normal", "text": "- `vector` - up to 2,000 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3939", "type": "linebreak", "version": 1}, {"id": "3940", "mode": "normal", "text": "- `halfvec` - up to 4,000 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3941", "type": "linebreak", "version": 1}, {"id": "3942", "mode": "normal", "text": "- `bit` - up to 64,000 dimensions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3943", "type": "linebreak", "version": 1}, {"id": "3944", "type": "linebreak", "version": 1}, {"id": "3945", "mode": "normal", "text": "### Query Options", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3946", "type": "linebreak", "version": 1}, {"id": "3947", "type": "linebreak", "version": 1}, {"id": "3948", "mode": "normal", "text": "Specify the number of probes (1 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3949", "type": "linebreak", "version": 1}, {"id": "3950", "type": "linebreak", "version": 1}, {"id": "3951", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3952", "type": "linebreak", "version": 1}, {"id": "3953", "mode": "normal", "text": "SET ivfflat.probes = 10;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3954", "type": "linebreak", "version": 1}, {"id": "3955", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3956", "type": "linebreak", "version": 1}, {"id": "3957", "type": "linebreak", "version": 1}, {"id": "3958", "mode": "normal", "text": "A higher value provides better recall at the cost of speed, and it can be set to the number of lists for exact nearest neighbor search (at which point the planner won’t use the index)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3959", "type": "linebreak", "version": 1}, {"id": "3960", "type": "linebreak", "version": 1}, {"id": "3961", "mode": "normal", "text": "Use `SET LOCAL` inside a transaction to set it for a single query", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3962", "type": "linebreak", "version": 1}, {"id": "3963", "type": "linebreak", "version": 1}, {"id": "3964", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3965", "type": "linebreak", "version": 1}, {"id": "3966", "mode": "normal", "text": "BEGIN;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3967", "type": "linebreak", "version": 1}, {"id": "3968", "mode": "normal", "text": "SET LOCAL ivfflat.probes = 10;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3969", "type": "linebreak", "version": 1}, {"id": "3970", "mode": "normal", "text": "SELECT ...", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3971", "type": "linebreak", "version": 1}, {"id": "3972", "mode": "normal", "text": "COMMIT;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3973", "type": "linebreak", "version": 1}, {"id": "3974", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3975", "type": "linebreak", "version": 1}, {"id": "3976", "type": "linebreak", "version": 1}, {"id": "3977", "mode": "normal", "text": "### Index Build Time", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3978", "type": "linebreak", "version": 1}, {"id": "3979", "type": "linebreak", "version": 1}, {"id": "3980", "mode": "normal", "text": "Speed up index creation on large tables by increasing the number of parallel workers (2 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3981", "type": "linebreak", "version": 1}, {"id": "3982", "type": "linebreak", "version": 1}, {"id": "3983", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3984", "type": "linebreak", "version": 1}, {"id": "3985", "mode": "normal", "text": "SET max_parallel_maintenance_workers = 7; -- plus leader", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3986", "type": "linebreak", "version": 1}, {"id": "3987", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3988", "type": "linebreak", "version": 1}, {"id": "3989", "type": "linebreak", "version": 1}, {"id": "3990", "mode": "normal", "text": "For a large number of workers, you may also need to increase `max_parallel_workers` (8 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3991", "type": "linebreak", "version": 1}, {"id": "3992", "type": "linebreak", "version": 1}, {"id": "3993", "mode": "normal", "text": "### Indexing Progress", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3994", "type": "linebreak", "version": 1}, {"id": "3995", "type": "linebreak", "version": 1}, {"id": "3996", "mode": "normal", "text": "Check [indexing progress](https://www.postgresql.org/docs/current/progress-reporting.html#CREATE-INDEX-PROGRESS-REPORTING)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "3997", "type": "linebreak", "version": 1}, {"id": "3998", "type": "linebreak", "version": 1}, {"id": "3999", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4000", "type": "linebreak", "version": 1}, {"id": "4001", "mode": "normal", "text": "SELECT phase, round(100.0 * tuples_done / nullif(tuples_total, 0), 1) AS \"%\" FROM pg_stat_progress_create_index;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4002", "type": "linebreak", "version": 1}, {"id": "4003", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4004", "type": "linebreak", "version": 1}, {"id": "4005", "type": "linebreak", "version": 1}, {"id": "4006", "mode": "normal", "text": "The phases for IVFFlat are:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4007", "type": "linebreak", "version": 1}, {"id": "4008", "type": "linebreak", "version": 1}, {"id": "4009", "mode": "normal", "text": "1. `initializing`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4010", "type": "linebreak", "version": 1}, {"id": "4011", "mode": "normal", "text": "2. `performing k-means`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4012", "type": "linebreak", "version": 1}, {"id": "4013", "mode": "normal", "text": "3. `assigning tuples`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4014", "type": "linebreak", "version": 1}, {"id": "4015", "mode": "normal", "text": "4. `loading tuples`", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4016", "type": "linebreak", "version": 1}, {"id": "4017", "type": "linebreak", "version": 1}, {"id": "4018", "mode": "normal", "text": "Note: `%` is only populated during the `loading tuples` phase", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4019", "type": "linebreak", "version": 1}, {"id": "4020", "type": "linebreak", "version": 1}, {"id": "4021", "mode": "normal", "text": "## Filtering", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4022", "type": "linebreak", "version": 1}, {"id": "4023", "type": "linebreak", "version": 1}, {"id": "4024", "mode": "normal", "text": "There are a few ways to index nearest neighbor queries with a `WHERE` clause.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4025", "type": "linebreak", "version": 1}, {"id": "4026", "type": "linebreak", "version": 1}, {"id": "4027", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4028", "type": "linebreak", "version": 1}, {"id": "4029", "mode": "normal", "text": "SELECT * FROM items WHERE category_id = 123 ORDER BY embedding <-> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4030", "type": "linebreak", "version": 1}, {"id": "4031", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4032", "type": "linebreak", "version": 1}, {"id": "4033", "type": "linebreak", "version": 1}, {"id": "4034", "mode": "normal", "text": "A good place to start is creating an index on the filter column. This can provide fast, exact nearest neighbor search in many cases. Postgres has a number of [index types](https://www.postgresql.org/docs/current/indexes-types.html) for this: B-tree (default), hash, GiST, SP-GiST, GIN, and BRIN.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4035", "type": "linebreak", "version": 1}, {"id": "4036", "type": "linebreak", "version": 1}, {"id": "4037", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4038", "type": "linebreak", "version": 1}, {"id": "4039", "mode": "normal", "text": "CREATE INDEX ON items (category_id);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4040", "type": "linebreak", "version": 1}, {"id": "4041", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4042", "type": "linebreak", "version": 1}, {"id": "4043", "type": "linebreak", "version": 1}, {"id": "4044", "mode": "normal", "text": "For multiple columns, consider a [multicolumn index](https://www.postgresql.org/docs/current/indexes-multicolumn.html).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4045", "type": "linebreak", "version": 1}, {"id": "4046", "type": "linebreak", "version": 1}, {"id": "4047", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4048", "type": "linebreak", "version": 1}, {"id": "4049", "mode": "normal", "text": "CREATE INDEX ON items (location_id, category_id);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4050", "type": "linebreak", "version": 1}, {"id": "4051", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4052", "type": "linebreak", "version": 1}, {"id": "4053", "type": "linebreak", "version": 1}, {"id": "4054", "mode": "normal", "text": "Exact indexes work well for conditions that match a low percentage of rows. Otherwise, [approximate indexes](#indexing) can work better.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4055", "type": "linebreak", "version": 1}, {"id": "4056", "type": "linebreak", "version": 1}, {"id": "4057", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4058", "type": "linebreak", "version": 1}, {"id": "4059", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_l2_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4060", "type": "linebreak", "version": 1}, {"id": "4061", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4062", "type": "linebreak", "version": 1}, {"id": "4063", "type": "linebreak", "version": 1}, {"id": "4064", "mode": "normal", "text": "With approximate indexes, filtering is applied *after* the index is scanned. If a condition matches 10% of rows, with HNSW and the default `hnsw.ef_search` of 40, only 4 rows will match on average. For more rows, increase `hnsw.ef_search`.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4065", "type": "linebreak", "version": 1}, {"id": "4066", "type": "linebreak", "version": 1}, {"id": "4067", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4068", "type": "linebreak", "version": 1}, {"id": "4069", "mode": "normal", "text": "SET hnsw.ef_search = 200;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4070", "type": "linebreak", "version": 1}, {"id": "4071", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4072", "type": "linebreak", "version": 1}, {"id": "4073", "type": "linebreak", "version": 1}, {"id": "4074", "mode": "normal", "text": "Starting with 0.8.0, you can enable [iterative index scans](#iterative-index-scans), which will automatically scan more of the index when needed.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4075", "type": "linebreak", "version": 1}, {"id": "4076", "type": "linebreak", "version": 1}, {"id": "4077", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4078", "type": "linebreak", "version": 1}, {"id": "4079", "mode": "normal", "text": "SET hnsw.iterative_scan = strict_order;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4080", "type": "linebreak", "version": 1}, {"id": "4081", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4082", "type": "linebreak", "version": 1}, {"id": "4083", "type": "linebreak", "version": 1}, {"id": "4084", "mode": "normal", "text": "If filtering by only a few distinct values, consider [partial indexing](https://www.postgresql.org/docs/current/indexes-partial.html).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4085", "type": "linebreak", "version": 1}, {"id": "4086", "type": "linebreak", "version": 1}, {"id": "4087", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4088", "type": "linebreak", "version": 1}, {"id": "4089", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw (embedding vector_l2_ops) WHERE (category_id = 123);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4090", "type": "linebreak", "version": 1}, {"id": "4091", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4092", "type": "linebreak", "version": 1}, {"id": "4093", "type": "linebreak", "version": 1}, {"id": "4094", "mode": "normal", "text": "If filtering by many different values, consider [partitioning](https://www.postgresql.org/docs/current/ddl-partitioning.html).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4095", "type": "linebreak", "version": 1}, {"id": "4096", "type": "linebreak", "version": 1}, {"id": "4097", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4098", "type": "linebreak", "version": 1}, {"id": "4099", "mode": "normal", "text": "CREATE TABLE items (embedding vector(3), category_id int) PARTITION BY LIST(category_id);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4100", "type": "linebreak", "version": 1}, {"id": "4101", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4102", "type": "linebreak", "version": 1}, {"id": "4103", "type": "linebreak", "version": 1}, {"id": "4104", "mode": "normal", "text": "## Iterative Index Scans", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4105", "type": "linebreak", "version": 1}, {"id": "4106", "type": "linebreak", "version": 1}, {"id": "4107", "mode": "normal", "text": "With approximate indexes, queries with filtering can return less results since filtering is applied *after* the index is scanned. Starting with 0.8.0, you can enable iterative index scans, which will automatically scan more of the index until enough results are found (or it reaches `hnsw.max_scan_tuples` or `ivfflat.max_probes`).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4108", "type": "linebreak", "version": 1}, {"id": "4109", "type": "linebreak", "version": 1}, {"id": "4110", "mode": "normal", "text": "Iterative scans can use strict or relaxed ordering.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4111", "type": "linebreak", "version": 1}, {"id": "4112", "type": "linebreak", "version": 1}, {"id": "4113", "mode": "normal", "text": "Strict ensures results are in the exact order by distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4114", "type": "linebreak", "version": 1}, {"id": "4115", "type": "linebreak", "version": 1}, {"id": "4116", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4117", "type": "linebreak", "version": 1}, {"id": "4118", "mode": "normal", "text": "SET hnsw.iterative_scan = strict_order;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4119", "type": "linebreak", "version": 1}, {"id": "4120", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4121", "type": "linebreak", "version": 1}, {"id": "4122", "type": "linebreak", "version": 1}, {"id": "4123", "mode": "normal", "text": "Relaxed allows results to be slightly out of order by distance, but provides better recall", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4124", "type": "linebreak", "version": 1}, {"id": "4125", "type": "linebreak", "version": 1}, {"id": "4126", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4127", "type": "linebreak", "version": 1}, {"id": "4128", "mode": "normal", "text": "SET hnsw.iterative_scan = relaxed_order;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4129", "type": "linebreak", "version": 1}, {"id": "4130", "mode": "normal", "text": "# or", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4131", "type": "linebreak", "version": 1}, {"id": "4132", "mode": "normal", "text": "SET ivfflat.iterative_scan = relaxed_order;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4133", "type": "linebreak", "version": 1}, {"id": "4134", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4135", "type": "linebreak", "version": 1}, {"id": "4136", "type": "linebreak", "version": 1}, {"id": "4137", "mode": "normal", "text": "With relaxed ordering, you can use a [materialized CTE](https://www.postgresql.org/docs/current/queries-with.html#QUERIES-WITH-CTE-MATERIALIZATION) to get strict ordering", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4138", "type": "linebreak", "version": 1}, {"id": "4139", "type": "linebreak", "version": 1}, {"id": "4140", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4141", "type": "linebreak", "version": 1}, {"id": "4142", "mode": "normal", "text": "WITH relaxed_results AS MATERIALIZED (", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4143", "type": "linebreak", "version": 1}, {"id": "4144", "mode": "normal", "text": "    SELECT id, embedding <-> ''[1,2,3]'' AS distance FROM items WHERE category_id = 123 ORDER BY distance LIMIT 5", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4145", "type": "linebreak", "version": 1}, {"id": "4146", "mode": "normal", "text": ") SELECT * FROM relaxed_results ORDER BY distance + 0;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4147", "type": "linebreak", "version": 1}, {"id": "4148", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4149", "type": "linebreak", "version": 1}, {"id": "4150", "type": "linebreak", "version": 1}, {"id": "4151", "mode": "normal", "text": "Note: `+ 0` is needed for Postgres 17+", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4152", "type": "linebreak", "version": 1}, {"id": "4153", "type": "linebreak", "version": 1}, {"id": "4154", "mode": "normal", "text": "For queries that filter by distance, use a materialized CTE and place the distance filter outside of it for best performance (due to the [current behavior](https://www.postgresql.org/message-id/flat/CAOdR5yGUoMQ6j7M5hNUXrySzaqZVGf_Ne%2B8fwZMRKTFxU1nbJg%40mail.gmail.com) of the Postgres executor)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4155", "type": "linebreak", "version": 1}, {"id": "4156", "type": "linebreak", "version": 1}, {"id": "4157", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4158", "type": "linebreak", "version": 1}, {"id": "4159", "mode": "normal", "text": "WITH nearest_results AS MATERIALIZED (", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4160", "type": "linebreak", "version": 1}, {"id": "4161", "mode": "normal", "text": "    SELECT id, embedding <-> ''[1,2,3]'' AS distance FROM items ORDER BY distance LIMIT 5", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4162", "type": "linebreak", "version": 1}, {"id": "4163", "mode": "normal", "text": ") SELECT * FROM nearest_results WHERE distance < 5 ORDER BY distance;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4164", "type": "linebreak", "version": 1}, {"id": "4165", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4166", "type": "linebreak", "version": 1}, {"id": "4167", "type": "linebreak", "version": 1}, {"id": "4168", "mode": "normal", "text": "Note: Place any other filters inside the CTE", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4169", "type": "linebreak", "version": 1}, {"id": "4170", "type": "linebreak", "version": 1}, {"id": "4171", "mode": "normal", "text": "### Iterative Scan Options", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4172", "type": "linebreak", "version": 1}, {"id": "4173", "type": "linebreak", "version": 1}, {"id": "4174", "mode": "normal", "text": "Since scanning a large portion of an approximate index is expensive, there are options to control when a scan ends.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4175", "type": "linebreak", "version": 1}, {"id": "4176", "type": "linebreak", "version": 1}, {"id": "4177", "mode": "normal", "text": "#### HNSW", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4178", "type": "linebreak", "version": 1}, {"id": "4179", "type": "linebreak", "version": 1}, {"id": "4180", "mode": "normal", "text": "Specify the max number of tuples to visit (20,000 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4181", "type": "linebreak", "version": 1}, {"id": "4182", "type": "linebreak", "version": 1}, {"id": "4183", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4184", "type": "linebreak", "version": 1}, {"id": "4185", "mode": "normal", "text": "SET hnsw.max_scan_tuples = 20000;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4186", "type": "linebreak", "version": 1}, {"id": "4187", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4188", "type": "linebreak", "version": 1}, {"id": "4189", "type": "linebreak", "version": 1}, {"id": "4190", "mode": "normal", "text": "Note: This is approximate and does not affect the initial scan", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4191", "type": "linebreak", "version": 1}, {"id": "4192", "type": "linebreak", "version": 1}, {"id": "4193", "mode": "normal", "text": "Specify the max amount of memory to use, as a multiple of `work_mem` (1 by default)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4194", "type": "linebreak", "version": 1}, {"id": "4195", "type": "linebreak", "version": 1}, {"id": "4196", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4197", "type": "linebreak", "version": 1}, {"id": "4198", "mode": "normal", "text": "SET hnsw.scan_mem_multiplier = 2;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4199", "type": "linebreak", "version": 1}, {"id": "4200", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4201", "type": "linebreak", "version": 1}, {"id": "4202", "type": "linebreak", "version": 1}, {"id": "4203", "mode": "normal", "text": "Note: Try increasing this if increasing `hnsw.max_scan_tuples` does not improve recall", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4204", "type": "linebreak", "version": 1}, {"id": "4205", "type": "linebreak", "version": 1}, {"id": "4206", "mode": "normal", "text": "#### IVFFlat", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4207", "type": "linebreak", "version": 1}, {"id": "4208", "type": "linebreak", "version": 1}, {"id": "4209", "mode": "normal", "text": "Specify the max number of probes", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4210", "type": "linebreak", "version": 1}, {"id": "4211", "type": "linebreak", "version": 1}, {"id": "4212", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4213", "type": "linebreak", "version": 1}, {"id": "4214", "mode": "normal", "text": "SET ivfflat.max_probes = 100;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4215", "type": "linebreak", "version": 1}, {"id": "4216", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4217", "type": "linebreak", "version": 1}, {"id": "4218", "type": "linebreak", "version": 1}, {"id": "4219", "mode": "normal", "text": "Note: If this is lower than `ivfflat.probes`, `ivfflat.probes` will be used", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4220", "type": "linebreak", "version": 1}, {"id": "4221", "type": "linebreak", "version": 1}, {"id": "4222", "mode": "normal", "text": "## Half-Precision Vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4223", "type": "linebreak", "version": 1}, {"id": "4224", "type": "linebreak", "version": 1}, {"id": "4225", "mode": "normal", "text": "Use the `halfvec` type to store half-precision vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4226", "type": "linebreak", "version": 1}, {"id": "4227", "type": "linebreak", "version": 1}, {"id": "4228", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4229", "type": "linebreak", "version": 1}, {"id": "4230", "mode": "normal", "text": "CREATE TABLE items (id bigserial PRIMARY KEY, embedding halfvec(3));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4231", "type": "linebreak", "version": 1}, {"id": "4232", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4233", "type": "linebreak", "version": 1}, {"id": "4234", "type": "linebreak", "version": 1}, {"id": "4235", "mode": "normal", "text": "## Half-Precision Indexing", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4236", "type": "linebreak", "version": 1}, {"id": "4237", "type": "linebreak", "version": 1}, {"id": "4238", "mode": "normal", "text": "Index vectors at half precision for smaller indexes", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4239", "type": "linebreak", "version": 1}, {"id": "4240", "type": "linebreak", "version": 1}, {"id": "4241", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4242", "type": "linebreak", "version": 1}, {"id": "4243", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw ((embedding::halfvec(3)) halfvec_l2_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4244", "type": "linebreak", "version": 1}, {"id": "4245", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4246", "type": "linebreak", "version": 1}, {"id": "4247", "type": "linebreak", "version": 1}, {"id": "4248", "mode": "normal", "text": "Get the nearest neighbors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4249", "type": "linebreak", "version": 1}, {"id": "4250", "type": "linebreak", "version": 1}, {"id": "4251", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4252", "type": "linebreak", "version": 1}, {"id": "4253", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding::halfvec(3) <-> ''[1,2,3]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4254", "type": "linebreak", "version": 1}, {"id": "4255", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4256", "type": "linebreak", "version": 1}, {"id": "4257", "type": "linebreak", "version": 1}, {"id": "4258", "mode": "normal", "text": "## Binary Vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4259", "type": "linebreak", "version": 1}, {"id": "4260", "type": "linebreak", "version": 1}, {"id": "4261", "mode": "normal", "text": "Use the `bit` type to store binary vectors ([example](https://github.com/pgvector/pgvector-python/blob/master/examples/imagehash/example.py))", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4262", "type": "linebreak", "version": 1}, {"id": "4263", "type": "linebreak", "version": 1}, {"id": "4264", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4265", "type": "linebreak", "version": 1}, {"id": "4266", "mode": "normal", "text": "CREATE TABLE items (id bigserial PRIMARY KEY, embedding bit(3));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4267", "type": "linebreak", "version": 1}, {"id": "4268", "mode": "normal", "text": "INSERT INTO items (embedding) VALUES (''000''), (''111'');", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4269", "type": "linebreak", "version": 1}, {"id": "4270", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4271", "type": "linebreak", "version": 1}, {"id": "4272", "type": "linebreak", "version": 1}, {"id": "4273", "mode": "normal", "text": "Get the nearest neighbors by Hamming distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4274", "type": "linebreak", "version": 1}, {"id": "4275", "type": "linebreak", "version": 1}, {"id": "4276", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4277", "type": "linebreak", "version": 1}, {"id": "4278", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding <~> ''101'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4279", "type": "linebreak", "version": 1}, {"id": "4280", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4281", "type": "linebreak", "version": 1}, {"id": "4282", "type": "linebreak", "version": 1}, {"id": "4283", "mode": "normal", "text": "Also supports Jaccard distance (`<%>`)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4284", "type": "linebreak", "version": 1}, {"id": "4285", "type": "linebreak", "version": 1}, {"id": "4286", "mode": "normal", "text": "## Binary Quantization", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4287", "type": "linebreak", "version": 1}, {"id": "4288", "type": "linebreak", "version": 1}, {"id": "4289", "mode": "normal", "text": "Use expression indexing for binary quantization", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4290", "type": "linebreak", "version": 1}, {"id": "4291", "type": "linebreak", "version": 1}, {"id": "4292", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4293", "type": "linebreak", "version": 1}, {"id": "4294", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw ((binary_quantize(embedding)::bit(3)) bit_hamming_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4295", "type": "linebreak", "version": 1}, {"id": "4296", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4297", "type": "linebreak", "version": 1}, {"id": "4298", "type": "linebreak", "version": 1}, {"id": "4299", "mode": "normal", "text": "Get the nearest neighbors by Hamming distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4300", "type": "linebreak", "version": 1}, {"id": "4301", "type": "linebreak", "version": 1}, {"id": "4302", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4303", "type": "linebreak", "version": 1}, {"id": "4304", "mode": "normal", "text": "SELECT * FROM items ORDER BY binary_quantize(embedding)::bit(3) <~> binary_quantize(''[1,-2,3]'') LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4305", "type": "linebreak", "version": 1}, {"id": "4306", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4307", "type": "linebreak", "version": 1}, {"id": "4308", "type": "linebreak", "version": 1}, {"id": "4309", "mode": "normal", "text": "Re-rank by the original vectors for better recall", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4310", "type": "linebreak", "version": 1}, {"id": "4311", "type": "linebreak", "version": 1}, {"id": "4312", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4313", "type": "linebreak", "version": 1}, {"id": "4314", "mode": "normal", "text": "SELECT * FROM (", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4315", "type": "linebreak", "version": 1}, {"id": "4316", "mode": "normal", "text": "    SELECT * FROM items ORDER BY binary_quantize(embedding)::bit(3) <~> binary_quantize(''[1,-2,3]'') LIMIT 20", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4317", "type": "linebreak", "version": 1}, {"id": "4318", "mode": "normal", "text": ") ORDER BY embedding <=> ''[1,-2,3]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4319", "type": "linebreak", "version": 1}, {"id": "4320", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4321", "type": "linebreak", "version": 1}, {"id": "4322", "type": "linebreak", "version": 1}, {"id": "4323", "mode": "normal", "text": "## Sparse Vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4324", "type": "linebreak", "version": 1}, {"id": "4325", "type": "linebreak", "version": 1}, {"id": "4326", "mode": "normal", "text": "Use the `sparsevec` type to store sparse vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4327", "type": "linebreak", "version": 1}, {"id": "4328", "type": "linebreak", "version": 1}, {"id": "4329", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4330", "type": "linebreak", "version": 1}, {"id": "4331", "mode": "normal", "text": "CREATE TABLE items (id bigserial PRIMARY KEY, embedding sparsevec(5));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4332", "type": "linebreak", "version": 1}, {"id": "4333", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4334", "type": "linebreak", "version": 1}, {"id": "4335", "type": "linebreak", "version": 1}, {"id": "4336", "mode": "normal", "text": "Insert vectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4337", "type": "linebreak", "version": 1}, {"id": "4338", "type": "linebreak", "version": 1}, {"id": "4339", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4340", "type": "linebreak", "version": 1}, {"id": "4341", "mode": "normal", "text": "INSERT INTO items (embedding) VALUES (''{1:1,3:2,5:3}/5''), (''{1:4,3:5,5:6}/5'');", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4342", "type": "linebreak", "version": 1}, {"id": "4343", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4344", "type": "linebreak", "version": 1}, {"id": "4345", "type": "linebreak", "version": 1}, {"id": "4346", "mode": "normal", "text": "The format is `{index1:value1,index2:value2}/dimensions` and indices start at 1 like SQL arrays", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4347", "type": "linebreak", "version": 1}, {"id": "4348", "type": "linebreak", "version": 1}, {"id": "4349", "mode": "normal", "text": "Get the nearest neighbors by L2 distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4350", "type": "linebreak", "version": 1}, {"id": "4351", "type": "linebreak", "version": 1}, {"id": "4352", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4353", "type": "linebreak", "version": 1}, {"id": "4354", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding <-> ''{1:3,3:1,5:2}/5'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4355", "type": "linebreak", "version": 1}, {"id": "4356", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4357", "type": "linebreak", "version": 1}, {"id": "4358", "type": "linebreak", "version": 1}, {"id": "4359", "mode": "normal", "text": "## Hybrid Search", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4360", "type": "linebreak", "version": 1}, {"id": "4361", "type": "linebreak", "version": 1}, {"id": "4362", "mode": "normal", "text": "Use together with Postgres [full-text search](https://www.postgresql.org/docs/current/textsearch-intro.html) for hybrid search.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4363", "type": "linebreak", "version": 1}, {"id": "4364", "type": "linebreak", "version": 1}, {"id": "4365", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4366", "type": "linebreak", "version": 1}, {"id": "4367", "mode": "normal", "text": "SELECT id, content FROM items, plainto_tsquery(''hello search'') query", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4368", "type": "linebreak", "version": 1}, {"id": "4369", "mode": "normal", "text": "    WHERE textsearch @@ query ORDER BY ts_rank_cd(textsearch, query) DESC LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4370", "type": "linebreak", "version": 1}, {"id": "4371", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4372", "type": "linebreak", "version": 1}, {"id": "4373", "type": "linebreak", "version": 1}, {"id": "4374", "mode": "normal", "text": "You can use [Reciprocal Rank Fusion](https://github.com/pgvector/pgvector-python/blob/master/examples/hybrid_search/rrf.py) or a [cross-encoder](https://github.com/pgvector/pgvector-python/blob/master/examples/hybrid_search/cross_encoder.py) to combine results.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4375", "type": "linebreak", "version": 1}, {"id": "4376", "type": "linebreak", "version": 1}, {"id": "4377", "mode": "normal", "text": "## Indexing Subvectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4378", "type": "linebreak", "version": 1}, {"id": "4379", "type": "linebreak", "version": 1}, {"id": "4380", "mode": "normal", "text": "Use expression indexing to index subvectors", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4381", "type": "linebreak", "version": 1}, {"id": "4382", "type": "linebreak", "version": 1}, {"id": "4383", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4384", "type": "linebreak", "version": 1}, {"id": "4385", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw ((subvector(embedding, 1, 3)::vector(3)) vector_cosine_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4386", "type": "linebreak", "version": 1}, {"id": "4387", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4388", "type": "linebreak", "version": 1}, {"id": "4389", "type": "linebreak", "version": 1}, {"id": "4390", "mode": "normal", "text": "Get the nearest neighbors by cosine distance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4391", "type": "linebreak", "version": 1}, {"id": "4392", "type": "linebreak", "version": 1}, {"id": "4393", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4394", "type": "linebreak", "version": 1}, {"id": "4395", "mode": "normal", "text": "SELECT * FROM items ORDER BY subvector(embedding, 1, 3)::vector(3) <=> subvector(''[1,2,3,4,5]''::vector, 1, 3) LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4396", "type": "linebreak", "version": 1}, {"id": "4397", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4398", "type": "linebreak", "version": 1}, {"id": "4399", "type": "linebreak", "version": 1}, {"id": "4400", "mode": "normal", "text": "Re-rank by the full vectors for better recall", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4401", "type": "linebreak", "version": 1}, {"id": "4402", "type": "linebreak", "version": 1}, {"id": "4403", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4404", "type": "linebreak", "version": 1}, {"id": "4405", "mode": "normal", "text": "SELECT * FROM (", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4406", "type": "linebreak", "version": 1}, {"id": "4407", "mode": "normal", "text": "    SELECT * FROM items ORDER BY subvector(embedding, 1, 3)::vector(3) <=> subvector(''[1,2,3,4,5]''::vector, 1, 3) LIMIT 20", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4408", "type": "linebreak", "version": 1}, {"id": "4409", "mode": "normal", "text": ") ORDER BY embedding <=> ''[1,2,3,4,5]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4410", "type": "linebreak", "version": 1}, {"id": "4411", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4412", "type": "linebreak", "version": 1}, {"id": "4413", "type": "linebreak", "version": 1}, {"id": "4414", "mode": "normal", "text": "## Performance", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4415", "type": "linebreak", "version": 1}, {"id": "4416", "type": "linebreak", "version": 1}, {"id": "4417", "mode": "normal", "text": "### Tuning", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4418", "type": "linebreak", "version": 1}, {"id": "4419", "type": "linebreak", "version": 1}, {"id": "4420", "mode": "normal", "text": "Use a tool like [PgTune](https://pgtune.leopard.in.ua/) to set initial values for Postgres server parameters. For instance, `shared_buffers` should typically be 25% of the server’s memory. You can find the config file with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4421", "type": "linebreak", "version": 1}, {"id": "4422", "type": "linebreak", "version": 1}, {"id": "4423", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4424", "type": "linebreak", "version": 1}, {"id": "4425", "mode": "normal", "text": "SHOW config_file;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4426", "type": "linebreak", "version": 1}, {"id": "4427", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4428", "type": "linebreak", "version": 1}, {"id": "4429", "type": "linebreak", "version": 1}, {"id": "4430", "mode": "normal", "text": "And check individual settings with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4431", "type": "linebreak", "version": 1}, {"id": "4432", "type": "linebreak", "version": 1}, {"id": "4433", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4434", "type": "linebreak", "version": 1}, {"id": "4435", "mode": "normal", "text": "SHOW shared_buffers;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4436", "type": "linebreak", "version": 1}, {"id": "4437", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4438", "type": "linebreak", "version": 1}, {"id": "4439", "type": "linebreak", "version": 1}, {"id": "4440", "mode": "normal", "text": "Be sure to restart Postgres for changes to take effect.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4441", "type": "linebreak", "version": 1}, {"id": "4442", "type": "linebreak", "version": 1}, {"id": "4443", "mode": "normal", "text": "### Loading", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4444", "type": "linebreak", "version": 1}, {"id": "4445", "type": "linebreak", "version": 1}, {"id": "4446", "mode": "normal", "text": "Use `COPY` for bulk loading data ([example](https://github.com/pgvector/pgvector-python/blob/master/examples/loading/example.py)).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4447", "type": "linebreak", "version": 1}, {"id": "4448", "type": "linebreak", "version": 1}, {"id": "4449", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4450", "type": "linebreak", "version": 1}, {"id": "4451", "mode": "normal", "text": "COPY items (embedding) FROM STDIN WITH (FORMAT BINARY);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4452", "type": "linebreak", "version": 1}, {"id": "4453", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4454", "type": "linebreak", "version": 1}, {"id": "4455", "type": "linebreak", "version": 1}, {"id": "4456", "mode": "normal", "text": "Add any indexes *after* loading the initial data for best performance.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4457", "type": "linebreak", "version": 1}, {"id": "4458", "type": "linebreak", "version": 1}, {"id": "4459", "mode": "normal", "text": "### Indexing", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4460", "type": "linebreak", "version": 1}, {"id": "4461", "type": "linebreak", "version": 1}, {"id": "4462", "mode": "normal", "text": "See index build time for [HNSW](#index-build-time) and [IVFFlat](#index-build-time-1).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4463", "type": "linebreak", "version": 1}, {"id": "4464", "type": "linebreak", "version": 1}, {"id": "4465", "mode": "normal", "text": "In production environments, create indexes concurrently to avoid blocking writes.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4466", "type": "linebreak", "version": 1}, {"id": "4467", "type": "linebreak", "version": 1}, {"id": "4468", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4469", "type": "linebreak", "version": 1}, {"id": "4470", "mode": "normal", "text": "CREATE INDEX CONCURRENTLY ...", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4471", "type": "linebreak", "version": 1}, {"id": "4472", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4473", "type": "linebreak", "version": 1}, {"id": "4474", "type": "linebreak", "version": 1}, {"id": "4475", "mode": "normal", "text": "### Querying", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4476", "type": "linebreak", "version": 1}, {"id": "4477", "type": "linebreak", "version": 1}, {"id": "4478", "mode": "normal", "text": "Use `EXPLAIN (ANALYZE, BUFFERS)` to debug performance.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4479", "type": "linebreak", "version": 1}, {"id": "4480", "type": "linebreak", "version": 1}, {"id": "4481", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4482", "type": "linebreak", "version": 1}, {"id": "4483", "mode": "normal", "text": "EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM items ORDER BY embedding <-> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4484", "type": "linebreak", "version": 1}, {"id": "4485", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4486", "type": "linebreak", "version": 1}, {"id": "4487", "type": "linebreak", "version": 1}, {"id": "4488", "mode": "normal", "text": "#### Exact Search", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4489", "type": "linebreak", "version": 1}, {"id": "4490", "type": "linebreak", "version": 1}, {"id": "4491", "mode": "normal", "text": "To speed up queries without an index, increase `max_parallel_workers_per_gather`.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4492", "type": "linebreak", "version": 1}, {"id": "4493", "type": "linebreak", "version": 1}, {"id": "4494", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4495", "type": "linebreak", "version": 1}, {"id": "4496", "mode": "normal", "text": "SET max_parallel_workers_per_gather = 4;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4497", "type": "linebreak", "version": 1}, {"id": "4498", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4499", "type": "linebreak", "version": 1}, {"id": "4500", "type": "linebreak", "version": 1}, {"id": "4501", "mode": "normal", "text": "If vectors are normalized to length 1 (like [OpenAI embeddings](https://platform.openai.com/docs/guides/embeddings/which-distance-function-should-i-use)), use inner product for best performance.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4502", "type": "linebreak", "version": 1}, {"id": "4503", "type": "linebreak", "version": 1}, {"id": "4504", "mode": "normal", "text": "```tsql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4505", "type": "linebreak", "version": 1}, {"id": "4506", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding <#> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4507", "type": "linebreak", "version": 1}, {"id": "4508", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4509", "type": "linebreak", "version": 1}, {"id": "4510", "type": "linebreak", "version": 1}, {"id": "4511", "mode": "normal", "text": "#### Approximate Search", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4512", "type": "linebreak", "version": 1}, {"id": "4513", "type": "linebreak", "version": 1}, {"id": "4514", "mode": "normal", "text": "To speed up queries with an IVFFlat index, increase the number of inverted lists (at the expense of recall).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4515", "type": "linebreak", "version": 1}, {"id": "4516", "type": "linebreak", "version": 1}, {"id": "4517", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4518", "type": "linebreak", "version": 1}, {"id": "4519", "mode": "normal", "text": "CREATE INDEX ON items USING ivfflat (embedding vector_l2_ops) WITH (lists = 1000);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4520", "type": "linebreak", "version": 1}, {"id": "4521", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4522", "type": "linebreak", "version": 1}, {"id": "4523", "type": "linebreak", "version": 1}, {"id": "4524", "mode": "normal", "text": "### Vacuuming", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4525", "type": "linebreak", "version": 1}, {"id": "4526", "type": "linebreak", "version": 1}, {"id": "4527", "mode": "normal", "text": "Vacuuming can take a while for HNSW indexes. Speed it up by reindexing first.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4528", "type": "linebreak", "version": 1}, {"id": "4529", "type": "linebreak", "version": 1}, {"id": "4530", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4531", "type": "linebreak", "version": 1}, {"id": "4532", "mode": "normal", "text": "REINDEX INDEX CONCURRENTLY index_name;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4533", "type": "linebreak", "version": 1}, {"id": "4534", "mode": "normal", "text": "VACUUM table_name;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4535", "type": "linebreak", "version": 1}, {"id": "4536", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4537", "type": "linebreak", "version": 1}, {"id": "4538", "type": "linebreak", "version": 1}, {"id": "4539", "mode": "normal", "text": "## Monitoring", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4540", "type": "linebreak", "version": 1}, {"id": "4541", "type": "linebreak", "version": 1}, {"id": "4542", "mode": "normal", "text": "Monitor performance with [pg_stat_statements](https://www.postgresql.org/docs/current/pgstatstatements.html) (be sure to add it to `shared_preload_libraries`).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4543", "type": "linebreak", "version": 1}, {"id": "4544", "type": "linebreak", "version": 1}, {"id": "4545", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4546", "type": "linebreak", "version": 1}, {"id": "4547", "mode": "normal", "text": "CREATE EXTENSION pg_stat_statements;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4548", "type": "linebreak", "version": 1}, {"id": "4549", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4550", "type": "linebreak", "version": 1}, {"id": "4551", "type": "linebreak", "version": 1}, {"id": "4552", "mode": "normal", "text": "Get the most time-consuming queries with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4553", "type": "linebreak", "version": 1}, {"id": "4554", "type": "linebreak", "version": 1}, {"id": "4555", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4556", "type": "linebreak", "version": 1}, {"id": "4557", "mode": "normal", "text": "SELECT query, calls, ROUND((total_plan_time + total_exec_time) / calls) AS avg_time_ms,", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4558", "type": "linebreak", "version": 1}, {"id": "4559", "mode": "normal", "text": "    ROUND((total_plan_time + total_exec_time) / 60000) AS total_time_min", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4560", "type": "linebreak", "version": 1}, {"id": "4561", "mode": "normal", "text": "    FROM pg_stat_statements ORDER BY total_plan_time + total_exec_time DESC LIMIT 20;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4562", "type": "linebreak", "version": 1}, {"id": "4563", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4564", "type": "linebreak", "version": 1}, {"id": "4565", "type": "linebreak", "version": 1}, {"id": "4566", "mode": "normal", "text": "Monitor recall by comparing results from approximate search with exact search.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4567", "type": "linebreak", "version": 1}, {"id": "4568", "type": "linebreak", "version": 1}, {"id": "4569", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4570", "type": "linebreak", "version": 1}, {"id": "4571", "mode": "normal", "text": "BEGIN;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4572", "type": "linebreak", "version": 1}, {"id": "4573", "mode": "normal", "text": "SET LOCAL enable_indexscan = off; -- use exact search", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4574", "type": "linebreak", "version": 1}, {"id": "4575", "mode": "normal", "text": "SELECT ...", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4576", "type": "linebreak", "version": 1}, {"id": "4577", "mode": "normal", "text": "COMMIT;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4578", "type": "linebreak", "version": 1}, {"id": "4579", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4580", "type": "linebreak", "version": 1}, {"id": "4581", "type": "linebreak", "version": 1}, {"id": "4582", "mode": "normal", "text": "## Scaling", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4583", "type": "linebreak", "version": 1}, {"id": "4584", "type": "linebreak", "version": 1}, {"id": "4585", "mode": "normal", "text": "Scale pgvector the same way you scale Postgres.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4586", "type": "linebreak", "version": 1}, {"id": "4587", "type": "linebreak", "version": 1}, {"id": "4588", "mode": "normal", "text": "Scale vertically by increasing memory, CPU, and storage on a single instance. Use existing tools to [tune parameters](#tuning) and [monitor performance](#monitoring).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4589", "type": "linebreak", "version": 1}, {"id": "4590", "type": "linebreak", "version": 1}, {"id": "4591", "mode": "normal", "text": "Scale horizontally with [replicas](https://www.postgresql.org/docs/current/hot-standby.html), or use [Citus](https://github.com/citusdata/citus) or another approach for sharding ([example](https://github.com/pgvector/pgvector-python/blob/master/examples/citus/example.py)).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4592", "type": "linebreak", "version": 1}, {"id": "4593", "type": "linebreak", "version": 1}, {"id": "4594", "mode": "normal", "text": "## Languages", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4595", "type": "linebreak", "version": 1}, {"id": "4596", "type": "linebreak", "version": 1}, {"id": "4597", "mode": "normal", "text": "Use pgvector from any language with a Postgres client. You can even generate and store vectors in one language and query them in another.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4598", "type": "linebreak", "version": 1}, {"id": "4599", "type": "linebreak", "version": 1}, {"id": "4600", "mode": "normal", "text": "Language | Libraries / Examples", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4601", "type": "linebreak", "version": 1}, {"id": "4602", "mode": "normal", "text": "--- | ---", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4603", "type": "linebreak", "version": 1}, {"id": "4604", "mode": "normal", "text": "Ada | [pgvector-ada](https://github.com/pgvector/pgvector-ada)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4605", "type": "linebreak", "version": 1}, {"id": "4606", "mode": "normal", "text": "Algol | [pgvector-algol](https://github.com/pgvector/pgvector-algol)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4607", "type": "linebreak", "version": 1}, {"id": "4608", "mode": "normal", "text": "C | [pgvector-c](https://github.com/pgvector/pgvector-c)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4609", "type": "linebreak", "version": 1}, {"id": "4610", "mode": "normal", "text": "C++ | [pgvector-cpp](https://github.com/pgvector/pgvector-cpp)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4611", "type": "linebreak", "version": 1}, {"id": "4612", "mode": "normal", "text": "C#, F#, Visual Basic | [pgvector-dotnet](https://github.com/pgvector/pgvector-dotnet)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4613", "type": "linebreak", "version": 1}, {"id": "4614", "mode": "normal", "text": "COBOL | [pgvector-cobol](https://github.com/pgvector/pgvector-cobol)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4615", "type": "linebreak", "version": 1}, {"id": "4616", "mode": "normal", "text": "Crystal | [pgvector-crystal](https://github.com/pgvector/pgvector-crystal)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4617", "type": "linebreak", "version": 1}, {"id": "4618", "mode": "normal", "text": "D | [pgvector-d](https://github.com/pgvector/pgvector-d)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4619", "type": "linebreak", "version": 1}, {"id": "4620", "mode": "normal", "text": "Dart | [pgvector-dart](https://github.com/pgvector/pgvector-dart)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4621", "type": "linebreak", "version": 1}, {"id": "4622", "mode": "normal", "text": "Elixir | [pgvector-elixir](https://github.com/pgvector/pgvector-elixir)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4623", "type": "linebreak", "version": 1}, {"id": "4624", "mode": "normal", "text": "Erlang | [pgvector-erlang](https://github.com/pgvector/pgvector-erlang)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4625", "type": "linebreak", "version": 1}, {"id": "4626", "mode": "normal", "text": "Fortran | [pgvector-fortran](https://github.com/pgvector/pgvector-fortran)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4627", "type": "linebreak", "version": 1}, {"id": "4628", "mode": "normal", "text": "Gleam | [pgvector-gleam](https://github.com/pgvector/pgvector-gleam)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4629", "type": "linebreak", "version": 1}, {"id": "4630", "mode": "normal", "text": "Go | [pgvector-go](https://github.com/pgvector/pgvector-go)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4631", "type": "linebreak", "version": 1}, {"id": "4632", "mode": "normal", "text": "Haskell | [pgvector-haskell](https://github.com/pgvector/pgvector-haskell)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4633", "type": "linebreak", "version": 1}, {"id": "4634", "mode": "normal", "text": "Java, Kotlin, Groovy, Scala | [pgvector-java](https://github.com/pgvector/pgvector-java)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4635", "type": "linebreak", "version": 1}, {"id": "4636", "mode": "normal", "text": "JavaScript, TypeScript | [pgvector-node](https://github.com/pgvector/pgvector-node)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4637", "type": "linebreak", "version": 1}, {"id": "4638", "mode": "normal", "text": "Julia | [Pgvector.jl](https://github.com/pgvector/Pgvector.jl)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4639", "type": "linebreak", "version": 1}, {"id": "4640", "mode": "normal", "text": "Lisp | [pgvector-lisp](https://github.com/pgvector/pgvector-lisp)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4641", "type": "linebreak", "version": 1}, {"id": "4642", "mode": "normal", "text": "Lua | [pgvector-lua](https://github.com/pgvector/pgvector-lua)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4643", "type": "linebreak", "version": 1}, {"id": "4644", "mode": "normal", "text": "Nim | [pgvector-nim](https://github.com/pgvector/pgvector-nim)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4645", "type": "linebreak", "version": 1}, {"id": "4646", "mode": "normal", "text": "OCaml | [pgvector-ocaml](https://github.com/pgvector/pgvector-ocaml)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4647", "type": "linebreak", "version": 1}, {"id": "4648", "mode": "normal", "text": "Pascal | [pgvector-pascal](https://github.com/pgvector/pgvector-pascal)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4649", "type": "linebreak", "version": 1}, {"id": "4650", "mode": "normal", "text": "Perl | [pgvector-perl](https://github.com/pgvector/pgvector-perl)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4651", "type": "linebreak", "version": 1}, {"id": "4652", "mode": "normal", "text": "PHP | [pgvector-php](https://github.com/pgvector/pgvector-php)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4653", "type": "linebreak", "version": 1}, {"id": "4654", "mode": "normal", "text": "Prolog | [pgvector-prolog](https://github.com/pgvector/pgvector-prolog)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4655", "type": "linebreak", "version": 1}, {"id": "4656", "mode": "normal", "text": "Python | [pgvector-python](https://github.com/pgvector/pgvector-python)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4657", "type": "linebreak", "version": 1}, {"id": "4658", "mode": "normal", "text": "R | [pgvector-r](https://github.com/pgvector/pgvector-r)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4659", "type": "linebreak", "version": 1}, {"id": "4660", "mode": "normal", "text": "Racket | [pgvector-racket](https://github.com/pgvector/pgvector-racket)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4661", "type": "linebreak", "version": 1}, {"id": "4662", "mode": "normal", "text": "Raku | [pgvector-raku](https://github.com/pgvector/pgvector-raku)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4663", "type": "linebreak", "version": 1}, {"id": "4664", "mode": "normal", "text": "Ruby | [pgvector-ruby](https://github.com/pgvector/pgvector-ruby), [Neighbor](https://github.com/ankane/neighbor)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4665", "type": "linebreak", "version": 1}, {"id": "4666", "mode": "normal", "text": "Rust | [pgvector-rust](https://github.com/pgvector/pgvector-rust)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4667", "type": "linebreak", "version": 1}, {"id": "4668", "mode": "normal", "text": "Swift | [pgvector-swift](https://github.com/pgvector/pgvector-swift)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4669", "type": "linebreak", "version": 1}, {"id": "4670", "mode": "normal", "text": "Tcl | [pgvector-tcl](https://github.com/pgvector/pgvector-tcl)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4671", "type": "linebreak", "version": 1}, {"id": "4672", "mode": "normal", "text": "Zig | [pgvector-zig](https://github.com/pgvector/pgvector-zig)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4673", "type": "linebreak", "version": 1}, {"id": "4674", "type": "linebreak", "version": 1}, {"id": "4675", "mode": "normal", "text": "## Frequently Asked Questions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4676", "type": "linebreak", "version": 1}, {"id": "4677", "type": "linebreak", "version": 1}, {"id": "4678", "mode": "normal", "text": "#### How many vectors can be stored in a single table?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4679", "type": "linebreak", "version": 1}, {"id": "4680", "type": "linebreak", "version": 1}, {"id": "4681", "mode": "normal", "text": "A non-partitioned table has a limit of 32 TB by default in Postgres. A partitioned table can have thousands of partitions of that size.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4682", "type": "linebreak", "version": 1}, {"id": "4683", "type": "linebreak", "version": 1}, {"id": "4684", "mode": "normal", "text": "#### Is replication supported?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4685", "type": "linebreak", "version": 1}, {"id": "4686", "type": "linebreak", "version": 1}, {"id": "4687", "mode": "normal", "text": "Yes, pgvector uses the write-ahead log (WAL), which allows for replication and point-in-time recovery.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4688", "type": "linebreak", "version": 1}, {"id": "4689", "type": "linebreak", "version": 1}, {"id": "4690", "mode": "normal", "text": "#### What if I want to index vectors with more than 2,000 dimensions?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4691", "type": "linebreak", "version": 1}, {"id": "4692", "type": "linebreak", "version": 1}, {"id": "4693", "mode": "normal", "text": "You can use [half-precision vectors](#half-precision-vectors) or [half-precision indexing](#half-precision-indexing) to index up to 4,000 dimensions or [binary quantization](#binary-quantization) to index up to 64,000 dimensions. Other options are [indexing subvectors](#indexing-subvectors) (for models that support it) or [dimensionality reduction](https://en.wikipedia.org/wiki/Dimensionality_reduction).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4694", "type": "linebreak", "version": 1}, {"id": "4695", "type": "linebreak", "version": 1}, {"id": "4696", "mode": "normal", "text": "#### Can I store vectors with different dimensions in the same column?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4697", "type": "linebreak", "version": 1}, {"id": "4698", "type": "linebreak", "version": 1}, {"id": "4699", "mode": "normal", "text": "You can use `vector` as the type (instead of `vector(n)`).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4700", "type": "linebreak", "version": 1}, {"id": "4701", "type": "linebreak", "version": 1}, {"id": "4702", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4703", "type": "linebreak", "version": 1}, {"id": "4704", "mode": "normal", "text": "CREATE TABLE embeddings (model_id bigint, item_id bigint, embedding vector, PRIMARY KEY (model_id, item_id));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4705", "type": "linebreak", "version": 1}, {"id": "4706", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4707", "type": "linebreak", "version": 1}, {"id": "4708", "type": "linebreak", "version": 1}, {"id": "4709", "mode": "normal", "text": "However, you can only create indexes on rows with the same number of dimensions (using [expression](https://www.postgresql.org/docs/current/indexes-expressional.html) and [partial](https://www.postgresql.org/docs/current/indexes-partial.html) indexing):", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4710", "type": "linebreak", "version": 1}, {"id": "4711", "type": "linebreak", "version": 1}, {"id": "4712", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4713", "type": "linebreak", "version": 1}, {"id": "4714", "mode": "normal", "text": "CREATE INDEX ON embeddings USING hnsw ((embedding::vector(3)) vector_l2_ops) WHERE (model_id = 123);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4715", "type": "linebreak", "version": 1}, {"id": "4716", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4717", "type": "linebreak", "version": 1}, {"id": "4718", "type": "linebreak", "version": 1}, {"id": "4719", "mode": "normal", "text": "and query with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4720", "type": "linebreak", "version": 1}, {"id": "4721", "type": "linebreak", "version": 1}, {"id": "4722", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4723", "type": "linebreak", "version": 1}, {"id": "4724", "mode": "normal", "text": "SELECT * FROM embeddings WHERE model_id = 123 ORDER BY embedding::vector(3) <-> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4725", "type": "linebreak", "version": 1}, {"id": "4726", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4727", "type": "linebreak", "version": 1}, {"id": "4728", "type": "linebreak", "version": 1}, {"id": "4729", "mode": "normal", "text": "#### Can I store vectors with more precision?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4730", "type": "linebreak", "version": 1}, {"id": "4731", "type": "linebreak", "version": 1}, {"id": "4732", "mode": "normal", "text": "You can use the `double precision[]` or `numeric[]` type to store vectors with more precision.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4733", "type": "linebreak", "version": 1}, {"id": "4734", "type": "linebreak", "version": 1}, {"id": "4735", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4736", "type": "linebreak", "version": 1}, {"id": "4737", "mode": "normal", "text": "CREATE TABLE items (id bigserial PRIMARY KEY, embedding double precision[]);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4738", "type": "linebreak", "version": 1}, {"id": "4739", "type": "linebreak", "version": 1}, {"id": "4740", "mode": "normal", "text": "-- use {} instead of [] for Postgres arrays", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4741", "type": "linebreak", "version": 1}, {"id": "4742", "mode": "normal", "text": "INSERT INTO items (embedding) VALUES (''{1,2,3}''), (''{4,5,6}'');", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4743", "type": "linebreak", "version": 1}, {"id": "4744", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4745", "type": "linebreak", "version": 1}, {"id": "4746", "type": "linebreak", "version": 1}, {"id": "4747", "mode": "normal", "text": "Optionally, add a [check constraint](https://www.postgresql.org/docs/current/ddl-constraints.html) to ensure data can be converted to the `vector` type and has the expected dimensions.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4748", "type": "linebreak", "version": 1}, {"id": "4749", "type": "linebreak", "version": 1}, {"id": "4750", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4751", "type": "linebreak", "version": 1}, {"id": "4752", "mode": "normal", "text": "ALTER TABLE items ADD CHECK (vector_dims(embedding::vector) = 3);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4753", "type": "linebreak", "version": 1}, {"id": "4754", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4755", "type": "linebreak", "version": 1}, {"id": "4756", "type": "linebreak", "version": 1}, {"id": "4757", "mode": "normal", "text": "Use [expression indexing](https://www.postgresql.org/docs/current/indexes-expressional.html) to index (at a lower precision):", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4758", "type": "linebreak", "version": 1}, {"id": "4759", "type": "linebreak", "version": 1}, {"id": "4760", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4761", "type": "linebreak", "version": 1}, {"id": "4762", "mode": "normal", "text": "CREATE INDEX ON items USING hnsw ((embedding::vector(3)) vector_l2_ops);", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4763", "type": "linebreak", "version": 1}, {"id": "4764", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4765", "type": "linebreak", "version": 1}, {"id": "4766", "type": "linebreak", "version": 1}, {"id": "4767", "mode": "normal", "text": "and query with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4768", "type": "linebreak", "version": 1}, {"id": "4769", "type": "linebreak", "version": 1}, {"id": "4770", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4771", "type": "linebreak", "version": 1}, {"id": "4772", "mode": "normal", "text": "SELECT * FROM items ORDER BY embedding::vector(3) <-> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4773", "type": "linebreak", "version": 1}, {"id": "4774", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4775", "type": "linebreak", "version": 1}, {"id": "4776", "type": "linebreak", "version": 1}, {"id": "4777", "mode": "normal", "text": "#### Do indexes need to fit into memory?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4778", "type": "linebreak", "version": 1}, {"id": "4779", "type": "linebreak", "version": 1}, {"id": "4780", "mode": "normal", "text": "No, but like other index types, you’ll likely see better performance if they do. You can get the size of an index with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4781", "type": "linebreak", "version": 1}, {"id": "4782", "type": "linebreak", "version": 1}, {"id": "4783", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4784", "type": "linebreak", "version": 1}, {"id": "4785", "mode": "normal", "text": "SELECT pg_size_pretty(pg_relation_size(''index_name''));", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4786", "type": "linebreak", "version": 1}, {"id": "4787", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4788", "type": "linebreak", "version": 1}, {"id": "4789", "type": "linebreak", "version": 1}, {"id": "4790", "mode": "normal", "text": "## Troubleshooting", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4791", "type": "linebreak", "version": 1}, {"id": "4792", "type": "linebreak", "version": 1}, {"id": "4793", "mode": "normal", "text": "#### Why isn’t a query using an index?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4794", "type": "linebreak", "version": 1}, {"id": "4795", "type": "linebreak", "version": 1}, {"id": "4796", "mode": "normal", "text": "The query needs to have an `ORDER BY` and `LIMIT`, and the `ORDER BY` must be the result of a distance operator (not an expression) in ascending order.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4797", "type": "linebreak", "version": 1}, {"id": "4798", "type": "linebreak", "version": 1}, {"id": "4799", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4800", "type": "linebreak", "version": 1}, {"id": "4801", "mode": "normal", "text": "-- index", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4802", "type": "linebreak", "version": 1}, {"id": "4803", "mode": "normal", "text": "ORDER BY embedding <=> ''[3,1,2]'' LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4804", "type": "linebreak", "version": 1}, {"id": "4805", "type": "linebreak", "version": 1}, {"id": "4806", "mode": "normal", "text": "-- no index", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4807", "type": "linebreak", "version": 1}, {"id": "4808", "mode": "normal", "text": "ORDER BY 1 - (embedding <=> ''[3,1,2]'') DESC LIMIT 5;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4809", "type": "linebreak", "version": 1}, {"id": "4810", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4811", "type": "linebreak", "version": 1}, {"id": "4812", "type": "linebreak", "version": 1}, {"id": "4813", "mode": "normal", "text": "You can encourage the planner to use an index for a query with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4814", "type": "linebreak", "version": 1}, {"id": "4815", "type": "linebreak", "version": 1}, {"id": "4816", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4817", "type": "linebreak", "version": 1}, {"id": "4818", "mode": "normal", "text": "BEGIN;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4819", "type": "linebreak", "version": 1}, {"id": "4820", "mode": "normal", "text": "SET LOCAL enable_seqscan = off;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4821", "type": "linebreak", "version": 1}, {"id": "4822", "mode": "normal", "text": "SELECT ...", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4823", "type": "linebreak", "version": 1}, {"id": "4824", "mode": "normal", "text": "COMMIT;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4825", "type": "linebreak", "version": 1}, {"id": "4826", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4827", "type": "linebreak", "version": 1}, {"id": "4828", "type": "linebreak", "version": 1}, {"id": "4829", "mode": "normal", "text": "Also, if the table is small, a table scan may be faster.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4830", "type": "linebreak", "version": 1}, {"id": "4831", "type": "linebreak", "version": 1}, {"id": "4832", "mode": "normal", "text": "#### Why isn’t a query using a parallel table scan?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4833", "type": "linebreak", "version": 1}, {"id": "4834", "type": "linebreak", "version": 1}, {"id": "4835", "mode": "normal", "text": "The planner doesn’t consider [out-of-line storage](https://www.postgresql.org/docs/current/storage-toast.html) in cost estimates, which can make a serial scan look cheaper. You can reduce the cost of a parallel scan for a query with:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4836", "type": "linebreak", "version": 1}, {"id": "4837", "type": "linebreak", "version": 1}, {"id": "4838", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4839", "type": "linebreak", "version": 1}, {"id": "4840", "mode": "normal", "text": "BEGIN;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4841", "type": "linebreak", "version": 1}, {"id": "4842", "mode": "normal", "text": "SET LOCAL min_parallel_table_scan_size = 1;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4843", "type": "linebreak", "version": 1}, {"id": "4844", "mode": "normal", "text": "SET LOCAL parallel_setup_cost = 1;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4845", "type": "linebreak", "version": 1}, {"id": "4846", "mode": "normal", "text": "SELECT ...", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4847", "type": "linebreak", "version": 1}, {"id": "4848", "mode": "normal", "text": "COMMIT;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4849", "type": "linebreak", "version": 1}, {"id": "4850", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4851", "type": "linebreak", "version": 1}, {"id": "4852", "type": "linebreak", "version": 1}, {"id": "4853", "mode": "normal", "text": "or choose to store vectors inline:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4854", "type": "linebreak", "version": 1}, {"id": "4855", "type": "linebreak", "version": 1}, {"id": "4856", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4857", "type": "linebreak", "version": 1}, {"id": "4858", "mode": "normal", "text": "ALTER TABLE items ALTER COLUMN embedding SET STORAGE PLAIN;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4859", "type": "linebreak", "version": 1}, {"id": "4860", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4861", "type": "linebreak", "version": 1}, {"id": "4862", "type": "linebreak", "version": 1}, {"id": "4863", "mode": "normal", "text": "#### Why are there less results for a query after adding an HNSW index?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4864", "type": "linebreak", "version": 1}, {"id": "4865", "type": "linebreak", "version": 1}, {"id": "4866", "mode": "normal", "text": "Results are limited by the size of the dynamic candidate list (`hnsw.ef_search`), which is 40 by default. There may be even less results due to dead tuples or filtering conditions in the query. Enabling [iterative index scans](#iterative-index-scans) can help address this.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4867", "type": "linebreak", "version": 1}, {"id": "4868", "type": "linebreak", "version": 1}, {"id": "4869", "mode": "normal", "text": "Also, note that `NULL` vectors are not indexed (as well as zero vectors for cosine distance).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4870", "type": "linebreak", "version": 1}, {"id": "4871", "type": "linebreak", "version": 1}, {"id": "4872", "mode": "normal", "text": "#### Why are there less results for a query after adding an IVFFlat index?", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4873", "type": "linebreak", "version": 1}, {"id": "4874", "type": "linebreak", "version": 1}, {"id": "4875", "mode": "normal", "text": "The index was likely created with too little data for the number of lists. Drop the index until the table has more data.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4876", "type": "linebreak", "version": 1}, {"id": "4877", "type": "linebreak", "version": 1}, {"id": "4878", "mode": "normal", "text": "```sql", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4879", "type": "linebreak", "version": 1}, {"id": "4880", "mode": "normal", "text": "DROP INDEX index_name;", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4881", "type": "linebreak", "version": 1}, {"id": "4882", "mode": "normal", "text": "```", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4883", "type": "linebreak", "version": 1}, {"id": "4884", "type": "linebreak", "version": 1}, {"id": "4885", "mode": "normal", "text": "Results can also be limited by the number of probes (`ivfflat.probes`). Enabling [iterative index scans](#iterative-index-scans) can address this.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4886", "type": "linebreak", "version": 1}, {"id": "4887", "type": "linebreak", "version": 1}, {"id": "4888", "mode": "normal", "text": "Also, note that `NULL` vectors are not indexed (as well as zero vectors for cosine distance).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4889", "type": "linebreak", "version": 1}, {"id": "4890", "type": "linebreak", "version": 1}, {"id": "4891", "mode": "normal", "text": "## Reference", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4892", "type": "linebreak", "version": 1}, {"id": "4893", "type": "linebreak", "version": 1}, {"id": "4894", "mode": "normal", "text": "- [Vector](#vector-type)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4895", "type": "linebreak", "version": 1}, {"id": "4896", "mode": "normal", "text": "- [Halfvec](#halfvec-type)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4897", "type": "linebreak", "version": 1}, {"id": "4898", "mode": "normal", "text": "- [Bit](#bit-type)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4899", "type": "linebreak", "version": 1}, {"id": "4900", "mode": "normal", "text": "- [Sparsevec](#sparsevec-type)", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4901", "type": "linebreak", "version": 1}, {"id": "4902", "type": "linebreak", "version": 1}, {"id": "4903", "mode": "normal", "text": "### Vector Type", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4904", "type": "linebreak", "version": 1}, {"id": "4905", "type": "linebreak", "version": 1}, {"id": "4906", "mode": "normal", "text": "Each vector takes `4 * dimensions + 8` bytes of storage. Each element is a single-precision floating-point number (like the `real` type in Postgres), and all elements must be finite (no `NaN`, `Infinity` or `-Infinity`). Vectors can have up to 16,000 dimensions.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4907", "type": "linebreak", "version": 1}, {"id": "4908", "type": "linebreak", "version": 1}, {"id": "4909", "mode": "normal", "text": "### Vector Operators", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4910", "type": "linebreak", "version": 1}, {"id": "4911", "type": "linebreak", "version": 1}, {"id": "4912", "mode": "normal", "text": "Operator | Description | Added", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4913", "type": "linebreak", "version": 1}, {"id": "4914", "mode": "normal", "text": "--- | --- | ---", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4915", "type": "linebreak", "version": 1}, {"id": "4916", "mode": "normal", "text": "\\+ | element-wise addition |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4917", "type": "linebreak", "version": 1}, {"id": "4918", "mode": "normal", "text": "\\- | element-wise subtraction |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4919", "type": "linebreak", "version": 1}, {"id": "4920", "mode": "normal", "text": "\\* | element-wise multiplication | 0.5.0", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4921", "type": "linebreak", "version": 1}, {"id": "4922", "mode": "normal", "text": "\\|\\| | concatenate | 0.7.0", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4923", "type": "linebreak", "version": 1}, {"id": "4924", "mode": "normal", "text": "<-> | Euclidean distance |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4925", "type": "linebreak", "version": 1}, {"id": "4926", "mode": "normal", "text": "<#> | negative inner product |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4927", "type": "linebreak", "version": 1}, {"id": "4928", "mode": "normal", "text": "<=> | cosine distance |", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4929", "type": "linebreak", "version": 1}, {"id": "4930", "mode": "normal", "text": "<+> | taxicab distance | 0.7.0", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4931", "type": "linebreak", "version": 1}, {"id": "4932", "type": "linebreak", "version": 1}, {"id": "4933", "mode": "normal", "text": "### Vector Functions", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4934", "type": "linebreak", "version": 1}, {"id": "4935", "type": "linebreak", "version": 1}, {"id": "4936", "mode": "normal", "text": "Function | Description | Added", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"id": "4937", "type": "linebreak", "version": 1}, {"id": "4938", "mode": "normal", "text": "--- | --- | ---", "type": "text", "style": "", "detail": 0