"children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "100", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "101", "mode": "normal", "text": "**22.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "102", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "104", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "105", "mode": "normal", "text": "**23.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "106", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "108", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "109", "mode": "normal", "text": "**24.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "110", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "112", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "113", "mode": "normal", "text": "**25.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "114", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "116", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "117", "mode": "normal", "text": "**26.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": nu