e": "", "textFormat": 0}, {"id": "1774", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1776", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1777", "mode": "normal", "text": "**447.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1778", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1780", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1781", "mode": "normal", "text": "**448.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1782", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1784", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1785", "mode": "normal", "text": "**449.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1786", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1788", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1789", "mode": "normal", "text": "**450.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1790", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1792", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1793", "mode": "normal", "text": "**451.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1794", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1796", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1797", "mode": "normal", "text": "**452.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1798", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1800", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1801", "mode": "normal", "text": "**453.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1802", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1804", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1805", "mode": "normal", "text": "**454.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1806", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1808", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1809", "mode": "normal", "text": "**455.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1810", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1812", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1813", "mode": "normal", "text": "**456.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1814", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1816", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1817", "mode": "normal", "text": "**457.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1818", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1820", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1821", "mode": "normal", "text": "**458.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1822", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1824", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1825", "mode": "normal", "text": "**459.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1826", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1828", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1829", "mode": "normal", "text": "**460.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1830", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1832", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1833", "mode": "normal", "text": "**461.** The municipality may cause to be sold at auction, by a bailiff, without judicial formalities and after giving the notices required by the Civil Code, any lost or forgotten movables it holds which have not been claimed within 60 days, any movables it holds which are referred to in article 943 of the Civil Code, and any movables without an owner which it collects in its territory. Vehicles without a motor or in a ruinous state which are left in public places and not claimed within 10 days are presumed to be abandoned and without an owner.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1834", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1836", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1837", "mode": "normal", "text": "**462.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1838", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1840", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1841", "mode": "normal", "text": "**463.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1842", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1844", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1845", "mode": "normal", "text": "**464.** The council may make by-laws:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1846", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1848", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1849", "mode": "normal", "text": "**465.** The fringe benefits accumulated by an officer or employee who is subsequently employed by another municipality which offers such benefits are transferable at the request of such officer or employee. The fringe benefits contemplated in the preceding paragraph include the benefits accumulated in a pension plan or fund administered by the employer, by the employer and the employees or by a third person on behalf of the municipal officers and employees; they do not include the benefits provided under a pension plan to which the Supplemental Pension Plans Act applies ( chapter R-15.1", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1850", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1852", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1853", "mode": "normal", "text": "**466.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1854", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1856", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1857", "mode": "normal", "text": "**467.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1858", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1860", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1861", "mode": "normal", "text": "**468.** Every municipality may make an agreement with any other municipality, regardless of the law governing it, relating to all or part of any field within its jurisdiction. Where several municipalities, by means of an agreement, share the services of an officer whom each municipality must have or appoint according to law, each party to the agreement is deemed to comply with that obligation.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1862", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1864", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1865", "mode": "normal", "text": "**469.** Where the conciliator fails to bring the municipalities to an agreement, the Commission municipale du Québec, at the request of one of them, notice of which is given to the other party and to the intermunicipal management board, if any, may make the arbitration award it considers equitable after hearing the municipalities concerned and the management board and examining the report of the conciliator remitted to it by the Minister. The provisions of the Code of Civil Procedure ( chapter C-25.01", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1866", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1868", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1869", "mode": "normal", "text": "**470.** The council may, by by-law, determine the guarantees to be given by any person at whose request it orders the execution of municipal work related to the erection of a new structure on the land concerned in the request.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1870", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1872", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1873", "mode": "normal", "text": "**471.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1874", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1876", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1877", "mode": "normal", "text": "**472.** The council may make by-laws to take a census of the inhabitants of the territory of the municipality, for the purpose of ascertaining their number, and of obtaining statistics regarding their social and economic condition.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1878", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1880", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1881", "mode": "normal", "text": "**475.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1882", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1884", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1885", "mode": "normal", "text": "**477.** The council may adopt by-laws relating to the administration of municipal finances. However, to ensure the sound administration of those finances, it must adopt a budget control and monitoring by-law that provides in particular for a means to guarantee the availability of funds before any decision authorizing an expenditure is made; the means may vary depending on the authority authorizing the expenditures or on the type of expenditures proposed.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1886", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1888", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1889", "mode": "normal", "text": "**478.** All fees, licences, fines, revenues, and taxes, accruing or belonging to the municipality, shall be paid to and received by the treasurer alone, or by the officers or employees designated by him for that purpose; and no other officer or employee shall, under any pretext, receive them, unless specially authorized by the council so to do.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1890", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1892", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1893", "mode": "normal", "text": "**479.** The fiscal year of the municipality shall begin on 1 January and end on 31 December of each year, and the taxes and yearly assessments shall be payable, subject to Division IV of Chapter XVIII of the Act respecting municipal taxation ( chapter F-2.1 The first paragraph applies to every municipality governed by this Act, even if a provision of its charter that came into force before 15 December 1977 repeals, replaces or amends, directly or indirectly, that paragraph. However, subject to section 3, the first paragraph does not apply to Ville de Laval.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1894", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1896", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1897", "mode": "normal", "text": "**480.** The council may, by resolution, whenever it sees fit, instruct the treasurer or any other officer or employee of the municipality to add to the amount of any taxes to be levied on taxable property in the territory of the municipality, a sum of not more than 10%, to cover losses, costs and bad debts.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1898", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1900", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1901", "mode": "normal", "text": "**481.** Taxes shall bear interest, at the rate of 5% per annum, from maturity, without its being for such purpose necessary that a special demand for payment be made. Subject to section 542, neither the municipal council nor the officers or employees of the municipality may remit any taxes or the interest thereon. The council, as often as it considers it expedient, may, by resolution, prescribe a rate of interest different from the rate provided in the first paragraph. The rate also applies to all debts unpaid before the passing of the resolution. The resolution of the council shall remain in force until it is repealed. The tax account shall indicate clearly the rate of interest in force at the time of its sending. The council may also, by resolution, grant a discount to every ratepayer who pays his taxes before they are due.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1902", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1904", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1905", "mode": "normal", "text": "**482.** (Repealed) .", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1906", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1908", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1909", "mode": "normal", "text": "**483.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1910", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1912", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1913", "mode": "normal", "text": "**484.** Arrears of municipal taxes shall be prescribed by three years. An application to the court for the recovery of a property tax filed before the tax is prescribed and served, not later than 60 days after the expiry of the prescription period, on any of the persons from whom the payment may be claimed under section 498, shall interrupt prescription with respect to all such persons.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1914", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1916", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1917", "mode": "normal", "text": "**485.** Subject to the Act respecting municipal taxation ( chapter F-2.1", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1918", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1920", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1921", "mode": "normal", "text": "**486.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1922", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1924", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1925", "mode": "normal", "text": "**487.** Notwithstanding any legislative provision inconsistent herewith contained in this Act or in the charter of a municipality governed in part by this Act, the council may impose the special tax for the payment of municipal works of any kind, including works of maintenance, according to either the municipal valuation or the area or the frontage of the taxable property subject to such tax. In the case of lots that are situated at a street corner or are not rectangular, the council may fix the frontage for assessment purposes, in the manner it sees fit. The council may also charge the cost of such works The council may combine the alternatives provided for in the second paragraph in the proportions it determines. In the case contemplated in subparagraph 3 of the second paragraph, the council must identify the immovables of those who benefit from the works or provide one or more criteria allowing to identify them. This section applies for the purposes of the payment of professional fees related to the works contemplated, whether or not they were carried out.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1926", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1928", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1929", "mode": "normal", "text": "**488.** Any municipality on the territory of which a public transit authority has jurisdiction pursuant to the Act respecting public transit authorities ( chapter S‐30.01", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1930", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1932", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1933", "mode": "normal", "text": "**489.** Any municipality may impose, in accordance with section 487, a special tax for the purposes of paying:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1934", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1936", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1937", "mode": "normal", "text": "**490.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1938", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1940", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1941", "mode": "normal", "text": "**491.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1942", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1944", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1945", "mode": "normal", "text": "**492.** Although the by-law of the council ordering the imposition and levying of certain duties or taxes, in the form of a licence, enacts that failure to pay the said fines or taxes shall constitute an offence, the council may, at its option, instead of instituting penal proceedings, sue for the recovery of the said duties or taxes, whether a licence be issued or not and whether the name of the person liable for the duties or taxes be entered or not in the valuation roll or in the collection roll.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1946", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1948", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1949", "mode": "normal", "text": "**493.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1950", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1952", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1953", "mode": "normal", "text": "**494.** The council may impose and levy an annual tax, to be fixed by by-law, on every stallion kept for breeding, on every horse aged three years and over, on every bull kept for breeding, on every other head of horned cattle over two years of age, on every dog and on every vehicle kept in the territory of the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1954", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1956", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1957", "mode": "normal", "text": "**495.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1958", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1960", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1961", "mode": "normal", "text": "**496.** In addition to the taxes mentioned in the foregoing sections of this subdivision 28, the council may also impose such taxes as are otherwise authorized by this Act. Every tax imposed by virtue of the foregoing provisions shall be payable annually and, subject to Division IV of Chapter XVIII of the Act respecting municipal taxation ( chapter F-2.1", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1962", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1964", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1965", "mode": "normal", "text": "**497.** Any person, not being the owner, who pays municipal taxes imposed in consideration of the land which he occupies, shall be subrogated without other formality, in the prior claims and legal hypothecs of the municipality on the immovable property of the owner, and may, unless there be an agreement to the contrary, withhold from the rent or from any other debt which he owes him, or recover from him by personal action, the amount which he has paid in principal, interest and costs. Saving the provisions of the preceding paragraph, any person, not being the debtor, who pays a municipal, property or personal, general or special tax, or the water-rates for a third party, with the consent in writing of the latter, is of right subrogated in the prior claims and legal hypothecs of the municipality on the movable and immovable property of the debtor and may recover from him the amount of taxes so paid. Such subrogation shall be of no effect unless the receipt given by the treasurer of the municipality who is bound to issue such receipt states that the payment was made by a third party for the debtor. The fact that the taxes were paid by a third party and that the latter is subrogated in the prior claims and legal hypothecs of the municipality must be noted in the books of the municipality and mentioned in every statement furnished by an officer or employee of the municipality respecting the taxes owed by any person or affecting an immovable. The omission of such mention shall render the municipality liable for the prejudice caused thereby to a third person, saving its recourse against the officer or employee in default.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1966", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1968", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1969", "mode": "normal", "text": "**498.** Municipal taxes, imposed on any immovable, may be collected from the tenant, occupant or other possessor of such immovable as well as from the owner thereof, or from any subsequent acquirer of such immovable, even where such tenant, occupant, possessor or acquirer is not entered on the valuation roll. In the case of any tax imposed on any partnership, in respect of the business of such partnership, such tax may be claimed and recovered in full from any member thereof.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1970", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1972", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1973", "mode": "normal", "text": "**499.** The council may pass such by-laws as may be necessary to enforce the collection of any special tax imposed in virtue of this Act. Nevertheless a sale under judicial authority shall not free an immovable from the taxes and special assessments imposed on such immovable which are not yet due.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1974", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1976", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1977", "mode": "normal", "text": "**501.** The treasurer shall make a general collection roll, each year, at the time fixed by the council, including all taxes, both general and special, then imposed, mentioning them separately. He shall also make a special collection roll whenever any special tax has been imposed, after the making of the general collection roll, or whenever he is ordered so to do by the council. Such special roll shall exist as a separate roll, only until the date fixed by the council for the preparation of the new general roll, and it must then be included in the new general roll which the treasurer shall prepare. Notwithstanding the foregoing, in the case of section 474.6, the special collection roll made following the imposition of a special tax as a consequence of the adoption of a supplementary budget shall be separate from the general collection roll even after the date fixed by the council for the preparation of the general roll.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1978", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1980", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1981", "mode": "normal", "text": "**502.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1982", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1984", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1985", "mode": "normal", "text": "**503.** The collection roll shall not be completed before 1 January nor until the budget of the municipality has been adopted. The treasurer, after having completed the collection roll, shall give public notice by which he announces that the general collection roll or the special roll, as the case may be, is deposited at his office and that the tax accounts shall be sent within the allotted time. The first and second paragraphs apply to every municipality governed by this Act, even if a provision of its charter that came into force before 15 December 1977 repeals, replaces or amends, directly or indirectly, one or both of those paragraphs. However, subject to section 3, the first and second paragraphs do not apply to Ville de Laval.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1986", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1988", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1989", "mode": "normal", "text": "**504.** Within sixty days following the day on which notice of the deposit of the roll was given, the treasurer shall transmit by mail, to every person entered on such roll, a demand for payment of the taxes. Such taxes shall be payable, subject to Division IV of Chapter XVIII of the Act respecting municipal taxation ( chapter F-2.1 This section applies subject to section 81 of the Act respecting municipal taxation.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1990", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1992", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1993", "mode": "normal", "text": "**505.** If the taxes are not paid at the expiry of the time prescribed therefor by section 504 or, as the case may be, any other period of time applicable under Division IV of Chapter XVIII of the Act respecting municipal taxation ( chapter F-2.1", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1994", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1996", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "1997", "mode": "normal", "text": "**506.** Such seizure and sale shall be made under a notice of execution prepared by the mayor and filed with the court office by the clerk of the Court of Québec or the clerk of the Superior Court, according to the amount claimed, addressed to a bailiff and executed by that officer, under his oath of office, according to the same rules and under the same responsibilities and penalties as a notice of execution against movable property issued by the Court of Québec. The mayor, in preparing such notice of execution, shall not incur any personal responsibility, but shall act under the responsibility of the municipality. The clerk of the Court of Québec or the clerk of the Superior Court shall file the notice of execution upon the filing of a certificate of the mayor establishing that the debt is exigible in the amount indicated therein.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "1998", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2000", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2001", "mode": "normal", "text": "**507.** If the debtor be absent, or if there be no person to open the doors of the house, cupboards, chests or other closed places, or in the event of a refusal to open the same, the seizing officer may, by an order of the clerk of the Court of Québec, of the clerk of the Superior Court or of any justice of the peace, be empowered to cause the same to be opened by the usual lawful means, in presence of two witnesses, with all necessary force.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2002", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2004", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2005", "mode": "normal", "text": "**508.** The sale may only be stopped by an opposition before the Court of Québec or the Superior Court, according to the amount claimed, where an opposition to the seizure of movables is permitted by the Code of Civil Procedure ( chapter C-25.01 In addition to the grounds mentioned in article 735 of the Code of Civil Procedure, opposition to annul a seizure may be taken to the competent court for any cause likely to affect the claim of the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2006", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2008", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2009", "mode": "normal", "text": "**509.** The payment of municipal taxes may be claimed also by an action brought in the name of the municipality, before the Court of Québec or the Municipal Court, if there be one. The special clerk of the Court of Québec has the same power as the special clerk of the Superior Court under article 181 of the Code of Civil Procedure ( chapter C-25.01 The defendant may obtain a stay of such action if the rolls, by‐laws, minutes or other municipal acts upon which it is based are sought to be quashed or annulled, unless section 252.1 of the Act respecting municipal taxation ( chapter F-2.1", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2010", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2012", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2013", "mode": "normal", "text": "**510.** An appeal shall lie to the Court of Appeal from the final decision in actions brought in virtue of section 509, if the sum claimed exceeds $7,000, not including interest.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2014", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2016", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2017", "mode": "normal", "text": "**511.** After the expiration of the six months next after the notice of deposit of the collection roll, the treasurer shall draw up a statement showing the immovables on which the taxes assessed have not been paid, in whole or in part.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2018", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2020", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2021", "mode": "normal", "text": "**512.** The council, after examining the statement filed by the treasurer, may order the clerk to sell such immovables at public auction, at the office of the council or at any other place mentioned in the order, in the manner hereinafter prescribed. The council may prescribe the payment period to be granted to the purchaser of an immovable. In such a case, the council shall prescribe the manner in which the immovable is to be put up for sale again should payment not be made within the allotted period. If the council grants a payment period, it may also provide that the bids are to be made remotely instead of being made in a physical place.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2022", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2024", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2025", "mode": "normal", "text": "**513.** Within 30 days of the order of the council, the clerk shall give public notice of the day, hour and place where the sale by auction will be held. The notice shall contain a description, according to the provisions of the Civil Code, of the immovables the sale whereof is so ordered, stating the name of the owner according to the assessment roll. However, the description of an immovable contemplated in section 7.1 is made by the description of the land on which it is situated and a summary description of the immovable contemplated accompanied, if possible, with the name and address of its owner and any other indication that may help to identify it. The notice may contain an abridged enumeration of the consecutive cadastral numbers of immovables belonging to the same owner. The notice must mention any decision made under the second or third paragraph of section 512 or under section 512.1. If bids are made remotely, the notice must state how and when bids will be received and specify the closing date.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2026", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2028", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2029", "mode": "normal", "text": "**514.** Such notice shall also be published twice in a newspaper circulated in the territory of the municipality. The sale cannot be held before the expiration of 15 days from the second publication. At the time of the first publication of the notice, the clerk must immediately transmit a copy thereof to the Land Registrar, and it shall be the duty of the Land Registrar to notify interested parties in the manner indicated by the Civil Code. Failure to notify the Land Registrar shall not render the proceedings null, but the officer or employee so in default shall be responsible for any damage resulting therefrom. When the sale of an immovable mentioned in the list and notice above mentioned is not proceeded with, the clerk in charge of such sale must inform the Land Registrar thereof.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2030", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2032", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2033", "mode": "normal", "text": "**515.** The clerk must also, by registered mail, within the time provided in section 513, notify of the date and place of such sale, each person whose property is to be sold and whose name appears on the valuation roll then in force with respect to such immovable. If such person has no known domicile in Québec, the formality of the notice shall not be necessary.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2034", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2036", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2037", "mode": "normal", "text": "**516.** If the sale is stopped by any proceeding which has been decided upon only after the day fixed for the sale, the notice of sale which is to be published in the newspapers shall be sufficient if it is drawn up in conformity with article 748 of the Code of Civil Procedure ( chapter C-25.01", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2038", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2040", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2041", "mode": "normal", "text": "**517.** At the time appointed for the sale, the clerk or some other person acting for him, shall sell to the highest bidder the immovables described in the notice upon which taxes are still due, after making known the amount to be raised on each of such immovables, including therein a part of the costs incurred for the sale, proportionate to the amount of the debt.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2042", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2044", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2045", "mode": "normal", "text": "**518.** The sale cannot be suspended except by an opposition taken in the Court of Québec of the district or in the Superior Court of the district, according to their respective jurisdiction, determined by the value of the immovable as entered on the valuation roll in force. The provisions of articles 735 and following of the Code of Civil Procedure ( chapter C-25.01 In addition to the grounds mentioned in article 735 of the Code of Civil Procedure, opposition to annul a seizure may be taken to the competent court for any cause likely to affect the claim of the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2046", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2048", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2049", "mode": "normal", "text": "**519.** Subject to a payment period prescribed under the second paragraph of section 512, the purchaser shall pay the amount of his purchase money immediately. In default of immediate payment, the person making the sale shall, either at once put up the immovable again for sale, or adjourn the sale to the following or any other day within eight days, by giving all persons present notice of such adjournment in an audible and intelligible voice.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2050", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2052", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2053", "mode": "normal", "text": "**520.** On payment by the purchaser of the amount of his purchase money, the clerk shall set forth, in a certificate made in duplicate and signed by himself, the particulars of the sale, and deliver a duplicate of such certificate to the purchaser.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2054", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2056", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2057", "mode": "normal", "text": "**521.** The purchaser shall thereupon be seized of the immovable adjuged, and may enter into possession thereof, subject to the same being redeemed within the year following, but shall not remove timber nor the buildings therefrom during the said year.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2058", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2060", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2061", "mode": "normal", "text": "**522.** Within the ten days following the adjudication, the clerk shall transmit to the Land Registrar a list of the immovables so sold for municipal taxes, with the name of the purchaser of each of such immovables. The clerk shall also, within the same time, inform by special notice, the property-owners or occupants of each immovable sold, of the sale thereof and of the particulars relating thereto mentioned in the list transmitted to the Land Registrar.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2062", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2064", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2065", "mode": "normal", "text": "**523.** The proceeds of the sale of each immovable shall be deposited in the office of the clerk of the Superior Court for the district, for distribution according to law. The clerk of the Superior Court shall obtain from the Land Registrar a copy of any page of the land register concerning the adjudged immovable that may be useful to him for the purposes of apportioning the proceeds of the sale. Where the clerk of the Superior Court considers it necessary and if the amount to be apportioned exceeds $1,000, he may obtain from the Land Registrar the certified statement described in article 3019 of the Civil Code. The clerk of the Superior Court shall pay out of the proceeds of the sale the cost of the copy of the page of the land register and, as the case may be, the cost of the certified statement. The proceeds of the sale shall be apportioned among the creditors according to the rules provided for in the case of a seizure of immovables in execution, without the formality of a scheme of collocation if the amount to be apportioned does not exceed $1,000. The clerk of the Superior Court, after distribution of the monies, shall deposit in the Land Registry Office a certified copy of the judgment of distribution, for the purpose of cancelling totally or partially the registration of the claims or hypothecs which have been paid in whole or in part.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2066", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2068", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2069", "mode": "normal", "text": "**524.** If, within one year from the day of the adjudication, the immovable adjudged has not been bought back or redeemed, according to the following provisions, the purchaser shall become the absolute owner thereof.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2070", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2072", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2073", "mode": "normal", "text": "**525.** Such purchaser, upon exhibiting the certificate of his purchase and upon proving the payment of all municipal and school taxes which in the meantime have become due thereon, shall be entitled, at the expiration of one year, to a deed of sale from the council. He is also entitled to such deed of sale at any time before the expiration of such time, with the consent of the owner of the said immovable or that of his legal representatives and of the prior or hypothecary creditors, which persons must intervene in the said deed to attest their consent.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2074", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2076", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2077", "mode": "normal", "text": "**526.** The deed of sale shall be executed in the name of the municipality, by the mayor or by the clerk, by deed before a notary.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2078", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2080", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2081", "mode": "normal", "text": "**527.** All the rights acquired by the purchaser shall pass to his heirs or successors.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2082", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2084", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2085", "mode": "normal", "text": "**528.** The sale made under the above provisions shall convey the ownership of the immovable adjudged.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2086", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2088", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2089", "mode": "normal", "text": "**529.** It shall vest in the purchaser all the rights of the original owner, and purge the immovable from all hypothecs to which it may be subject, except, subject to the reserve contained in the last paragraph of this section, the claim for special taxes imposed on the immovable and not yet due, claims to constituted ground rents, to seigniorial rights, to rents substituted therefor, to school taxes or assessments and also the sums due to trustees for the assessments imposed upon the said immovable to defray the expenses of building or repairs to churches, vestries, parsonages and burial grounds; but the arrears of the rents, taxes and assessments above mentioned, due before the sale, shall be extinguished by the sale, unless there has been lodged in the office of the council, at least eight days before the sale, a certified account of such arrears, taxes or assessments. The registration of the deed of sale shall effect the cancellation of the registration of the hypothecs registered against the immovable which are discharged by the sale. The adjudication of an immovable to a municipality having an interest by reason of a prior claim or legal hypothec upon the said immovable purges the latter from all constituted ground rents, rents under emphyteusis and rents replacing seigniorial rights, counting from the date of the adjudication and as long as the immovable remains the property of the said municipality. Such rents shall again be an encumbrance upon the immovable, but for the future only, counting from the date when the immovable ceases to be the property of the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2090", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2092", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2093", "mode": "normal", "text": "**530.** Suits for the cancellation of the sale of an immovable made under the above provisions and the right to invoke the illegality thereof shall be prescribed by twelve months counting from the date of the adjudication.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2094", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2096", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2097", "mode": "normal", "text": "**531.** An immovable sold for taxes may be redeemed by the owner or his legal representatives, at any time within the year following the day of adjudication, by paying to the purchaser the price of sale, including the cost of the certificate of adjudication, with interest at the rate of ten per cent per annum, a fraction of a year being counted as a whole year. When the immovable sold is vacant land, the amount payable to the purchaser shall also include the total of the municipal and school taxes, general and special, imposed upon the immovable from the date of adjudication to the date of redemption, if they have been paid by the purchaser; if they have not been paid, the redemption shall free the purchaser therefrom and shall bind the owner to pay them.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2098", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2100", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2101", "mode": "normal", "text": "**532.** The owner shall be then entitled to obtain from the purchaser, but at his own cost, a deed before a notary establishing the reimbursement of the monies and the redemption of the immovable. The registration of an authentic copy of such deed restores to him the right of ownership of the immovable possessed by him at the time of sale, subject to the prior claims and hypothecary claims which encumbered it at that date, less what was paid on them by the distribution of the proceeds of the sale.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2102", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2104", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2105", "mode": "normal", "text": "**533.** Any person, whether authorized or not, may, unless a deed of sale has been effected under the second paragraph of section 525, redeem such immovable in the same manner, but only in the name and for the benefit of the person who was the owner thereof at the time of the adjudication.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2106", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2108", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2109", "mode": "normal", "text": "**534.** The person so redeeming, shall be entitled to be reimbursed, by the owner, the amount he has paid, with interest at 8%.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2110", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2112", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2113", "mode": "normal", "text": "**536.** Whenever immovables situated in the territory of a municipality are sold for municipal or school taxes, the municipality may bid upon and acquire such immovables through the mayor or other person, upon the authorization of the council, without having to immediately pay the amount of the adjudication. The municipality may also bid upon and acquire such immovables, at any sale under judicial authority or other sale having the same effect.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2114", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2116", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2117", "mode": "normal", "text": "**537.** The municipality shall cause to be entered in its name the immovables so purchased, in the valuation and collection rolls and special apportionment rolls, and shall tax them like any other taxable immovable, and such immovables shall remain liable for municipal and school taxes as any other immovables and shall be assessed the same. However, the school taxes thus imposed shall not be exigible from the municipality. If the right to redeem be exercised, the redemption price shall include, over and above the amount paid by the municipality for the immovable, and the interest at 10% thereon, the amount of general or special municipal and school taxes assessed on such immovables from the date of the adjudication to the date of the redemption, or the instalments due on such taxes if they are payable by instalments, as well as the sums of money due to the municipality for taxes unpaid by the distribution of the proceeds of the sale. After the redemption, the instalments of special taxes not yet due shall continue to affect the immovable redeemed, and the owner shall be liable thereof.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2118", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2120", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2121", "mode": "normal", "text": "**538.** If the right to redeem be not exercised within one year from the adjudication, the clerk, the bailiff or the trustee, as the case may be, shall draw up and sign a deed of sale in favour of the municipality, and have it registered.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2122", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2124", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2125", "mode": "normal", "text": "**539.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2126", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2128", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2129", "mode": "normal", "text": "**540.** A municipality may bid upon and acquire any immovable property hypothecated in its favour under any law authorizing it to make a loan to help those who have suffered disaster, at any sale under judicial authority or at any sale having the same effect. The municipality’s bid must not however exceed the amount of its claim in capital, interest and costs, together with a sufficient sum to satisfy any prior or hypothecary claim having prior or equal rank to that of such claim.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2130", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2132", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2133", "mode": "normal", "text": "**542.** The council may, by resolution, exempt the poor of the territory of the municipality from the payment of taxes.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2134", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2136", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2137", "mode": "normal", "text": "**543.** The municipality may borrow money for all objects within its jurisdiction.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2138", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2140", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2141", "mode": "normal", "text": "**544.** Every by-law ordering a loan must However, a by-law ordering a loan for the purpose of capital expenditures may mention the object of the by-law only in general terms and indicate only the amount and maximum term of the loan if For the purposes of subparagraph 2 of the second paragraph, the total amount of the loans ordered by the municipality is deemed to exceed the maximum amount provided for in that subparagraph on the adoption of a loan by-law that would cause the total amount to exceed that maximum amount if it came into force.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2142", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2144", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2145", "mode": "normal", "text": "**545.** (Replaced).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2146", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2148", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2149", "mode": "normal", "text": "**546.** (Replaced).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2150", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2152", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2153", "mode": "normal", "text": "**547.** The by-law ordering a loan must also provide, in accordance with the following rules, for the expense incurred for interest and for the establishment of a sinking fund. The sinking fund may be established, either by means of a special tax imposed by the by-law and levied annually until the expiry of the term of the loan upon the taxable immovable property in the territory of the municipality or upon the immovable property of owners or occupants liable for the payment of the loan, or by annually setting aside for that purpose a portion of the general revenues of the municipality. In both instances, the sum paid each year into the sinking fund must be sufficient to yield, with compound interest thereon at the rate of 3.5% per annum, the capital to be paid at maturity. The sum necessary to provide for expense incurred for interest may likewise be taken from the general revenues, or levied annually by a special tax imposed by the by-law on the taxable immovable property in the territory of the municipality or on that of the owners or occupants liable for the payment of the loan. Where a special tax is imposed to be levied annually, it may be levied from the coming into force of the by-law. Until the bonds, notes or other securities are issued, the tax may be levied at a rate sufficient to pay incidental charges in respect of the loan and its object, including interest on temporary loans.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2154", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2156", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2157", "mode": "normal", "text": "**548.** If the loan be reimbursable in yearly or half-yearly payments or by annuities, the monies destined for the sinking fund shall be used each year for the repayment of a part of the principal of the loan. When the loan is repayable otherwise than by yearly or half-yearly payments or by annuities, such sums of money shall be deposited or invested in accordance with the provisions of sections 34 and following of the Act respecting municipal debts and loans ( chapter D-7 Whenever it is obligatory to entrust the administration of a sinking fund to the Minister of Finance, but that mandate has not been given as prescribed, the Minister of Revenue, as well as any trustee, bondholder, ratepayer or any other interested party, may, by an action in law, compel the municipality to make such deposit, and in case a judgment to that effect is obtained against the municipality, the provisions of this Act, respecting the execution of judgments against municipalities and contained in sections 591 to 604, shall apply.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2158", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2160", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2161", "mode": "normal", "text": "**549.** Loans may be contracted by a municipality by means of an issue of bonds, notes or other securities. Every bond must bear the seal of the municipality and be signed by the mayor and the treasurer. However, if the treasurer and his assistant are absent or if they are unable or refuse to act, or if the offices of treasurer and assistant treasurer are vacant, another officer or employee of the municipality designated by the council may sign the bonds in their place. The signature of the mayor may be printed, lithographed or engraved on the bonds. The signature of the treasurer may also, with the authorization of the council, be printed, lithographed or engraved on the bonds. Every bond heretofore or hereafter issued shall be deemed to have been validly signed if it bears the signature of each person who is required to sign it under this section on the date the bond bears or on the date it was signed. Such bonds may be made payable to a named holder, to his order or to bearer. They shall be payable at the dates fixed by the by-law, and shall bear interest payable semi-annually at the dates also fixed by the by-law. If a bond is registered in the name of a person under the Act respecting municipal debts and loans ( chapter D-7 A transfer in accordance with the Act respecting the transfer of securities and the establishment of security entitlements ( chapter T-11.002", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2162", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2164", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2165", "mode": "normal", "text": "**550.** The bonds shall mention:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2166", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2168", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2169", "mode": "normal", "text": "**551.** Coupons may be annexed to each bond, each of which shall constitute the title for one instalment of interest. Such coupons shall be payable to the person entitled to payment of the interest when the interest specified therein falls due, whether the bearer, the person in whose name the bond is registered or the endorsee, and shall bear an indicating number as well as the number of the bond to which they are attached. They shall be signed by the persons contemplated in the second paragraph of section 549; but a facsimile of the signatures of those persons, printed, lithographed or engraved on the coupons, shall be sufficient. On payment of the interest, the coupons shall be handed to the treasurer, and the possession of any coupon by such officer or employee shall be proof that the interest specified therein has been paid. Any municipality not governed by the provisions of this section may enact, by by-law of its council, that these provisions shall apply to the said municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2170", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2172", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2173", "mode": "normal", "text": "**552.** The principal and interest of every bond shall be secured by the general funds of the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2174", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2176", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2177", "mode": "normal", "text": "**553.** The council may stipulate, in the by-law, that the loan will be repayable in annual or semi-annual payments covering a portion of the principal, the interest being represented by coupons, or in annuities covering both interest and a portion of the principal and represented by titles or bonds maturing annually or semi-annually. In both cases, the by-law shall contain a table of the payments or annuities, showing the amount payable at each date of maturity, the number of bonds redeemable annually or semi-annually and the amount of each of them.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2178", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2180", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2181", "mode": "normal", "text": "**554.** The municipality shall sell the bonds it is authorized to issue, by adjudication, on written tenders, after a notice, published in the Gazette officielle du Québec Such notice shall state the amount, term and mode of repayment of the loan, the rate of interest, and the place, day and hour fixed for the opening of tenders. The council shall not, without the previous authorization of the Minister of Finance, award the contract to any person other than the one who has made the most advantageous tender within the time fixed. The Minister of Finance may, however, authorize the municipality to sell its bonds by mutual agreement without the formalities prescribed by this section, on the conditions that he may deem expedient to impose.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2182", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2184", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2185", "mode": "normal", "text": "**555.** The council may, by resolution, commission the Minister of Finance to receive and open the tenders provided for in section 554 on behalf and in the name of such municipality. Where such is the case, the tenders must be sent to or deposited at the place determined by the Minister as notified by him to the clerk of the municipality together with the day and time fixed for the opening of the tenders. For the purposes of this section, the Minister may act through the representative designated by him. The resolution contemplated in the first paragraph binds the Minister from the time he receives certified copy of it until he receives certified copy of a resolution to the contrary. Where the Minister is commissioned under the first paragraph, the adjudication is effected by the Minister without a resolution of the municipal council being required.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2186", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2188", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2189", "mode": "normal", "text": "**556.** Every by-law ordering a loan shall be submitted to the qualified voters and to the Minister of Municipal Affairs, Regions and Land Occupancy for approval. However, a loan by-law the sole purpose of which is the preparation of plans and specifications or the financing of an amount the municipality must pay in respect of an unfunded actuarial liability or an amount established pursuant to subparagraph 4 of the second paragraph of section 137 of the Supplemental Pension Plans Act ( chapter R‐15.1 Likewise, a loan by-law requires only the approval of the Minister if A loan by-law also requires only the approval of the Minister if a subsidy has been granted for at least 50% of the expenditure to be incurred and payment of the subsidy is assured by the Government or one of its ministers or bodies. In such a case, the Minister may, however, require that the loan by-law be submitted for approval to the qualified voters. This section has effect notwithstanding any inconsistent provision of any charter or special Act, unless such charter or Act dispenses with the formality of approval by the qualified voters.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2190", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2192", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2193", "mode": "normal", "text": "**557.** Where a referendum poll is required pursuant to the Act respecting elections and referendums in municipalities ( chapter E-2.2 If the result of the computation provided for in the first paragraph is a number that includes a fraction, the fraction shall be counted as a unit.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2194", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2196", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2197", "mode": "normal", "text": "**558.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2198", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2200", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2201", "mode": "normal", "text": "**559.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2202", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2204", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2205", "mode": "normal", "text": "**560.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2206", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2208", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2209", "mode": "normal", "text": "**561.** Where the repayment of a loan is to be borne by the owners of immovables of a part only of the territory of the municipality or by those who benefit from the works as determined under section 487, the tax to be levied each year during the term of the loan shall be assessed only on the immovables of the owners concerned. The tax must be sufficient to pay the interest each year and make up the capital repayable at the maturity of the bonds, notes or other securities.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2210", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2212", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2213", "mode": "normal", "text": "**562.** The clerk shall transmit a certified copy of the loan by-law to the Minister of Municipal Affairs, Regions and Land Occupancy, together with every other document he may require. The clerk must provide the Minister with any information requested by him with respect to the by-law.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2214", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2216", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2217", "mode": "normal", "text": "**563.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2218", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2220", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2221", "mode": "normal", "text": "**564.** Notwithstanding any inconsistent provision, the council may amend a loan by-law by a resolution requiring no approval if the amendment does not change the object of the loan and For the purposes of the first paragraph, the burden on the ratepayers is considered not to be increased where the additional cost arising from a change in the borrowing method is connected with the administrative expenses of the new borrowing method and nothing else. The clerk shall send a copy of the resolution passed under this section to the Minister of Municipal Affairs, Regions and Land Occupancy.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2222", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2224", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2225", "mode": "normal", "text": "**565.** The council may, by by-law requiring only the approval of the Minister of Municipal Affairs, Regions and Land Occupancy, amend or replace any special tax imposed by a loan by-law under which notes, bonds or other securities have been issued. At least 30 days before it is submitted to the Minister, the amending by-law must be published in accordance with the procedure prescribed for the publication of public notices, with a notice stating that any person wishing to object to the approval of the by-law must so inform the Minister in writing within the 30 days. If the special tax is imposed under a loan resolution, the council may proceed by resolution rather than by by-law. This section applies, with the necessary modifications, to the approval of the resolution.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2226", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2228", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2229", "mode": "normal", "text": "**566.** Sections 564 and 565 apply to every loan by-law or resolution, except in the case of a temporary loan, whatever the Act under which it was passed.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2230", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2232", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2233", "mode": "normal", "text": "**568.** The member of a council who, knowingly, by his vote or otherwise, authorizes the municipality to make or makes on its behalf a loan exceeding the approved amount or a loan which has not received one or another of the approvals contemplated in this subdivision 30, when such approval is required by law or by the charter, may be declared disqualified to hold any municipal office for two years and may be held personally liable towards the municipality for any loss or damage suffered by it. The liability provided in the first paragraph is joint and several and it applies to every officer or employee of the municipality who knowingly is a party to the unlawful act. Proceedings for the declaration of disqualification shall be taken in accordance with subparagraph 4 of the first paragraph of article 529 and articles 532 to 535 of the Code of Civil Procedure ( chapter C‐25.01 Disqualification may also be declared by way of an action for declaration of disqualification under the Act respecting elections and referendums in municipalities ( chapter E‐2.2", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2234", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2236", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2237", "mode": "normal", "text": "**570.** The council may, by complying with the provisions of sections 571 and 572 and the expropriation procedure established by law, The foregoing provisions of this section shall not be regarded as restricting the right which the council may otherwise have to acquire, by mutual agreement, immovables for the same purposes.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2238", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2240", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2241", "mode": "normal", "text": "**571.** The council may not, without the authorization of the Government expropriate the following properties:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2242", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2244", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2245", "mode": "normal", "text": "**572.** A special notice of the petition to obtain the authorization contemplated in section 571 must be notified to each owner concerned and such notice shall state that after 30 days the petition will be submitted to the Government and that any opposition must be forwarded in writing to the Minister of Municipal Affairs, Regions and Land Occupancy within such time.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2246", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2248", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2249", "mode": "normal", "text": "**574.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2250", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2252", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2253", "mode": "normal", "text": "**575.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2254", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2256", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2257", "mode": "normal", "text": "**576.** Penal proceedings for an offence under a provision of this Act, the charter, a by-law, a resolution or an order of the council may be instituted by the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2258", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2260", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2261", "mode": "normal", "text": "**577.** Where a municipality institutes penal proceedings before any court other than a municipal court, the fines imposed for an offence under a provision of this Act, the charter, a by-law, a resolution or an order of the council belong to the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2262", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2264", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2265", "mode": "normal", "text": "**578.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2266", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2268", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2269", "mode": "normal", "text": "**579.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2270", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2272", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2273", "mode": "normal", "text": "**580.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2274", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2276", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2277", "mode": "normal", "text": "**581.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2278", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2280", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2281", "mode": "normal", "text": "**582.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2282", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2284", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2285", "mode": "normal", "text": "**583.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2286", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2288", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2289", "mode": "normal", "text": "**584.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2290", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2292", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2293", "mode": "normal", "text": "**586.** Every action, suit or claim against the municipality or any of its officers or employees, for damages occasioned by faults, or illegalities, shall be prescribed by six months from the day on which the cause of action accrued, any provision of law to the contrary notwithstanding.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2294", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2296", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2297", "mode": "normal", "text": "**587.** Every person who, by any excavation in or obstruction upon any street of the municipality, not authorized by law or the by-laws of the municipality, renders such street unsafe for travel, or who, by negligence in the management of any such excavation or obstruction as shall be authorized, or by failure to maintain proper guards or lights thereat, renders such street insufficient or unsafe for travel, shall be liable for any damage, not caused by the negligence of the injured party, to whomsoever resulting by reason of such obstruction or negligence; and no action shall be maintained against the municipality for such damage, unless such person be joined as defendant, if the municipality calls upon the plaintiff so to do, at the same time informing him of the name, residence and quality of such person.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2298", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2300", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2301", "mode": "normal", "text": "**588.** In case of judgment against the defendants under section 587, execution shall first be issued only against the defendant other than the municipality, and the municipality shall not be required to take steps to pay such judgment, including costs of execution against the other defendant, until the notice of execution is returned unsatisfied, or unless there be an opposition to or contestation of the seizure for reasons other than matters of form. If the municipality pays such judgment it shall become subrogated in the rights of the plaintiff therein, and may enforce payment of the same from the other defendant, and shall be entitled to execution therein against him, and to take such other proceedings as judgment creditors are entitled to take.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2302", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2304", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2305", "mode": "normal", "text": "**589.** When any suit or action is commenced against the municipality, service therein shall be made upon the clerk or the clerk-treasurer, at his office or domicile.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2306", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2308", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2309", "mode": "normal", "text": "**590.** Any provision of law to the contrary notwithstanding, no judgment rendered against the municipality for a pecuniary condemnation only shall be executory before the expiration of thirty days after the date thereof.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2310", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2312", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2313", "mode": "normal", "text": "**591.** Whenever a copy of a judgment condemning the municipality to pay a sum of money has been notified to the office of the council, the treasurer shall, forthwith, upon being authorized by the council or by the mayor, pay the amount thereof out of the funds at his disposal, according to the by-laws made under section 477.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2314", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2316", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2317", "mode": "normal", "text": "**592.** If there be no funds, or if those at the disposal of the treasurer be not sufficient, the council shall, immediately after the notification of the judgment, order the treasurer, by resolution, to levy, on the taxable property within the territory of the municipality, a sum sufficient to pay the amount due with the interest and costs. The council may also proceed by way of a loan by-law requiring only the approval of the Minister of Municipal Affairs, Regions and Land Occupancy.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2318", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2320", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2321", "mode": "normal", "text": "**593.** The court which rendered the judgment may, on application to that effect presented either in term or in vacation, grant to the council any time which it deems necessary to levy the moneys required.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2322", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2324", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2325", "mode": "normal", "text": "**594.** If the judgment have not been satisfied within two months after the notification thereof at the office of the council, or at the expiration of the time granted by the court or agreed upon by the parties, the person in whose favour such judgment was rendered may, on producing the return of such notification, give a bailiff instructions to proceed with the execution against the municipality. The bailiff files the notice of execution with the court office, in the record concerned.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2326", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2328", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2329", "mode": "normal", "text": "**595.** Such notice of execution shall be signed by the clerk, sealed with the seal of the court, and addressed to the clerk of the district in which the territory of such municipality is situated, enjoining him, among other things:", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2330", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2332", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2333", "mode": "normal", "text": "**596.** The clerk shall execute without delay, either personally or by his officers, all the requirements of such writ or of any other order subsequently issued by the court.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2334", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2336", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2337", "mode": "normal", "text": "**597.** The clerk shall have free access to the registers, valuation rolls, collection rolls and other documents deposited in the office of the council, and he may demand the services of the officers or employees of the municipality, under the same penalties as if such services were required by the council itself.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2338", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2340", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2341", "mode": "normal", "text": "**598.** The clerk shall take possession of the valuation roll and other documents which are necessary to him for the execution of the judgment and orders of the court. On the refusal or neglect of the municipal council or of the officers or employees of the municipality to deliver up such documents, he may take possession thereof.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2342", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2344", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2345", "mode": "normal", "text": "**599.** If it be impossible for the seizing officer to obtain the valuation roll which should serve as a basis for the collection of the moneys, or if there be no such valuation roll, the clerk shall, without delay, proceed to make a valuation of the taxable property; and he may base the special collection roll for the money to be levied, on such valuation as if it were the valuation roll in force. The costs incurred in making such valuation, as taxed by the court issuing the judgment, shall form part of the costs of execution and shall be recoverable from the municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2346", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2348", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2349", "mode": "normal", "text": "**600.** The fees, costs and disbursements of the clerk shall be taxed in the discretion of the judge of the court issuing the judgment.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2350", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2352", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2353", "mode": "normal", "text": "**601.** The clerk shall transmit to the office of the council a copy of his special collection roll, and any other roll or document whereof he has taken possession, after having levied the whole amount set forth in the writ of execution, together with interest and costs.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2354", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2356", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2357", "mode": "normal", "text": "**602.** The arrears due, in virtue of the clerk’s special collection roll, shall belong to the municipality and may be recovered by such municipality in the same manner as any other municipal tax. If any surplus remain in the hands of the clerk, it shall belong to such municipality.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2358", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2360", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2361", "mode": "normal", "text": "**603.** The clerk may obtain from the court any order calculated to facilitate and ensure the complete execution of the notice filed with the court office.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2362", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2364", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2365", "mode": "normal", "text": "**604.** If the municipality, against which any judgment has been rendered, holds property in its own name, such property may be seized and taken in execution in the ordinary manner prescribed in the Code of Civil Procedure ( chapter C-25.01 If any such property be hypothecated for the debt which is the object of the judgment, it shall be sold before the notice of execution mentioned in section 594 is filed.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2366", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2368", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2369", "mode": "normal", "text": "**605.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2370", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2372", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2373", "mode": "normal", "text": "**606.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2374", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2376", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2377", "mode": "normal", "text": "**607.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2378", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2380", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2381", "mode": "normal", "text": "**608.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2382", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2384", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2385", "mode": "normal", "text": "**609.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2386", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2388", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2389", "mode": "normal", "text": "**610.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2390", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2392", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2393", "mode": "normal", "text": "**611.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2394", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2396", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2397", "mode": "normal", "text": "**612.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2398", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2400", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2401", "mode": "normal", "text": "**613.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2402", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2404", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2405", "mode": "normal", "text": "**614.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2406", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2408", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"id": "2409", "mode": "normal", "text": "**615.** (Repealed).", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2410", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"id": "2412", "type": "paragraph", "format": "", "indent": 0, "version": 1, "children":